use crate::geometry;
use crate::ir::{ProjectedEvent, ProjectedProperty, ProjectedType, ProjectionIr};

pub(crate) fn emit_safe_module(ir: &ProjectionIr) -> String {
    let mut out = String::from(
        "//! Generated by rustolonia-bindgen. Do not edit.\n\
         #![allow(dead_code)]\n\n\
         use rustolonia_sys as sys;\n\
         use crate::{runtime::{with_factory, AsControl, EventSubscription}, Result};\n\n",
    );
    out.push_str(&geometry::emit_safe_structs());
    if ir
        .types
        .iter()
        .any(|t| t.properties.iter().any(|p| p.kind == "DataTemplate"))
    {
        out.push_str(
            "/// A data template handed to an item-content property: Rust owns Match and\n\
             /// Build through the `rustolonia_sys::data_template` CCW.\n\
             #[derive(Clone, Debug)]\n\
             pub struct DataTemplate {\n\
             \x20   pub(crate) raw: sys::ComPtr<sys::IAvnDataTemplate>,\n\
             }\n\n\
             impl PartialEq for DataTemplate {\n\
             \x20   fn eq(&self, other: &Self) -> bool {\n\
             \x20       std::ptr::eq(self.raw.as_raw(), other.raw.as_raw())\n\
             \x20   }\n\
             }\n\
             impl Eq for DataTemplate {}\n\n\
             impl DataTemplate {\n\
             \x20   pub(crate) fn from_raw(raw: sys::ComPtr<sys::IAvnDataTemplate>) -> Self {\n\
             \x20       Self { raw }\n\
             \x20   }\n\
             }\n\n",
        );
    }
    out.push_str(
        "/// Safe mirror of `Avalonia.PixelPoint`, marshalled as `sys::AvnPixelPoint`.\n\
         #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]\n\
         pub struct PixelPoint {\n\
         \x20   pub x: i32,\n\
         \x20   pub y: i32,\n\
         }\n\n\
         impl PixelPoint {\n\
         \x20   pub const fn new(x: i32, y: i32) -> Self {\n\
         \x20       Self { x, y }\n\
         \x20   }\n\
         \x20   pub(crate) fn from_abi(value: sys::AvnPixelPoint) -> Self {\n\
         \x20       Self { x: value.x, y: value.y }\n\
         \x20   }\n\
         \x20   pub(crate) fn to_abi(self) -> sys::AvnPixelPoint {\n\
         \x20       sys::AvnPixelPoint { x: self.x, y: self.y }\n\
         \x20   }\n\
         }\n\n\
         impl From<(i32, i32)> for PixelPoint {\n\
         \x20   fn from((x, y): (i32, i32)) -> Self {\n\
         \x20       Self::new(x, y)\n\
         \x20   }\n\
         }\n\n\
         impl From<[i32; 2]> for PixelPoint {\n\
         \x20   fn from([x, y]: [i32; 2]) -> Self {\n\
         \x20       Self::new(x, y)\n\
         \x20   }\n\
         }\n\n",
    );
    if ir
        .types
        .iter()
        .any(|t| t.properties.iter().any(|p| p.kind == "Variant"))
    {
        out.push_str(&crate::variant::emit_safe_enum());
    }
    if ir.brush_interface_name.is_some() {
        out.push_str(&emit_brush());
    }
    if ir.gradient_brush_interface_name.is_some() {
        out.push_str(&emit_gradient_brush());
    }

    let regular_enums: std::collections::HashSet<&str> = ir
        .enums
        .iter()
        .filter(|projected_enum| !projected_enum.is_flags)
        .map(|projected_enum| projected_enum.full_name.as_str())
        .collect();
    let flags_enums: std::collections::HashSet<&str> = ir
        .enums
        .iter()
        .filter(|projected_enum| projected_enum.is_flags)
        .map(|projected_enum| projected_enum.full_name.as_str())
        .collect();
    for projected_enum in &ir.enums {
        let mut values = Vec::new();
        for value in &projected_enum.values {
            if !values
                .iter()
                .any(|existing: &&crate::ir::ProjectedEnumValue| existing.value == value.value)
            {
                values.push(value);
            }
        }
        if projected_enum.is_flags {
            out.push_str(&emit_flags_struct(projected_enum, &values));
            continue;
        }
        out.push_str("#[repr(i32)]\n#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]\n");
        out.push_str(&format!("pub enum {} {{\n", projected_enum.name));
        for value in &values {
            out.push_str(&format!("    {} = {},\n", value.name, value.value));
        }
        out.push_str("}\n\n");
        out.push_str(&format!(
            "impl TryFrom<i32> for {} {{\n\
             \x20   type Error = crate::Error;\n\
             \x20   fn try_from(value: i32) -> Result<Self> {{\n\
             \x20       match value {{\n",
            projected_enum.name
        ));
        for value in &values {
            out.push_str(&format!(
                "            {} => Ok(Self::{}),\n",
                value.value, value.name
            ));
        }
        out.push_str(
            "            _ => Err(crate::Error::InvalidEnumValue(value)),\n        }\n    }\n}\n\n",
        );
    }

    out.push_str(&emit_safe_event_types(ir, &flags_enums, &regular_enums));

    for collection in unique_collections(ir) {
        out.push_str(&emit_collection(collection));
        out.push('\n');
    }

    for ty in ir.types.iter().filter(|ty| ty.kind == "Class") {
        out.push_str(&emit_type(ir, ty, &flags_enums, &regular_enums));
        out.push('\n');
    }
    out.truncate(out.trim_end().len());
    out.push('\n');
    out
}

fn emit_brush() -> String {
    String::from(
        "/// A solid colour brush: the only brush shape that crosses the ABI.\n\
         ///\n\
         /// `Background`, `BorderBrush` and `Foreground` are carried as a colour plus an\n\
         /// opacity. Gradient, drawing and visual brushes are not projected; reading one back\n\
         /// from a control fails instead of degrading to a nearest colour.\n\
         #[derive(Clone, Copy, Debug, PartialEq)]\n\
         pub struct Brush {\n\
         \x20   pub color: Color,\n\
         \x20   pub opacity: f64,\n\
         }\n\n\
         impl Brush {\n\
         \x20   /// A fully opaque solid colour.\n\
         \x20   pub const fn solid(color: Color) -> Self {\n\
         \x20       Self {\n\
         \x20           color,\n\
         \x20           opacity: 1.0,\n\
         \x20       }\n\
         \x20   }\n\n\
         \x20   /// A solid colour drawn at `opacity`, where 1.0 is fully opaque.\n\
         \x20   pub const fn new(color: Color, opacity: f64) -> Self {\n\
         \x20       Self { color, opacity }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn to_raw(self) -> Result<sys::ComPtr<sys::IAvnBrush>> {\n\
         \x20       with_factory(|factory| {\n\
         \x20           factory.create_solid_color_brush(self.color.into(), self.opacity)\n\
         \x20       })\n\
         \x20   }\n\n\
         \x20   pub(crate) fn from_raw(raw: &sys::ComPtr<sys::IAvnBrush>) -> Result<Self> {\n\
         \x20       Ok(Self {\n\
         \x20           color: raw.color()?.into(),\n\
         \x20           opacity: raw.opacity()?,\n\
         \x20       })\n\
         \x20   }\n\
         }\n\n\
         impl From<Color> for Brush {\n\
         \x20   fn from(color: Color) -> Self {\n\
         \x20       Self::solid(color)\n\
         \x20   }\n\
         }\n\n\
         impl From<(u8, u8, u8)> for Brush {\n\
         \x20   fn from((r, g, b): (u8, u8, u8)) -> Self {\n\
         \x20       Self::solid(Color::rgb(r, g, b))\n\
         \x20   }\n\
         }\n\n",
    )
}

fn emit_gradient_brush() -> String {
    String::from(
        "/// Spread behaviour for a gradient outside its `[0, 1]` stop range.\n\
         /// Mirrors `Avalonia.Media.GradientSpreadMethod`.\n\
         #[repr(i32)]\n\
         #[derive(Clone, Copy, Debug, PartialEq, Eq)]\n\
         pub enum SpreadMethod {\n\
         \x20   Pad = 0,\n\
         \x20   Reflect = 1,\n\
         \x20   Repeat = 2,\n\
         }\n\n\
         impl TryFrom<i32> for SpreadMethod {\n\
         \x20   type Error = crate::Error;\n\
         \x20   fn try_from(value: i32) -> Result<Self> {\n\
         \x20       match value {\n\
         \x20           0 => Ok(Self::Pad),\n\
         \x20           1 => Ok(Self::Reflect),\n\
         \x20           2 => Ok(Self::Repeat),\n\
         \x20           _ => Err(crate::Error::InvalidEnumValue(value)),\n\
         \x20       }\n\
         \x20   }\n\
         }\n\n\
         /// Whether a gradient coordinate is relative to the shape's bounding box or an\n\
         /// absolute value. Mirrors `Avalonia.RelativeUnit`.\n\
         #[repr(i32)]\n\
         #[derive(Clone, Copy, Debug, PartialEq, Eq)]\n\
         pub enum RelativeUnit {\n\
         \x20   Relative = 0,\n\
         \x20   Absolute = 1,\n\
         }\n\n\
         impl TryFrom<i32> for RelativeUnit {\n\
         \x20   type Error = crate::Error;\n\
         \x20   fn try_from(value: i32) -> Result<Self> {\n\
         \x20       match value {\n\
         \x20           0 => Ok(Self::Relative),\n\
         \x20           1 => Ok(Self::Absolute),\n\
         \x20           _ => Err(crate::Error::InvalidEnumValue(value)),\n\
         \x20       }\n\
         \x20   }\n\
         }\n\n\
         /// A point whose X/Y may each be relative to the shape's bounding box.\n\
         #[derive(Clone, Copy, Debug, PartialEq)]\n\
         pub struct RelativePoint {\n\
         \x20   pub x: f64,\n\
         \x20   pub y: f64,\n\
         \x20   pub unit: RelativeUnit,\n\
         }\n\n\
         impl RelativePoint {\n\
         \x20   pub const fn new(x: f64, y: f64, unit: RelativeUnit) -> Self {\n\
         \x20       Self { x, y, unit }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn to_abi(self) -> sys::AvnRelativePoint {\n\
         \x20       sys::AvnRelativePoint { x: self.x, y: self.y, unit: self.unit as i32 }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn from_abi(value: sys::AvnRelativePoint) -> Result<Self> {\n\
         \x20       Ok(Self { x: value.x, y: value.y, unit: RelativeUnit::try_from(value.unit)? })\n\
         \x20   }\n\
         }\n\n\
         /// A scalar (for example a radius) that may be relative to the shape's bounding box.\n\
         #[derive(Clone, Copy, Debug, PartialEq)]\n\
         pub struct RelativeScalar {\n\
         \x20   pub scalar: f64,\n\
         \x20   pub unit: RelativeUnit,\n\
         }\n\n\
         impl RelativeScalar {\n\
         \x20   pub const fn new(scalar: f64, unit: RelativeUnit) -> Self {\n\
         \x20       Self { scalar, unit }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn to_abi(self) -> sys::AvnRelativeScalar {\n\
         \x20       sys::AvnRelativeScalar { scalar: self.scalar, unit: self.unit as i32 }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn from_abi(value: sys::AvnRelativeScalar) -> Result<Self> {\n\
         \x20       Ok(Self { scalar: value.scalar, unit: RelativeUnit::try_from(value.unit)? })\n\
         \x20   }\n\
         }\n\n\
         /// A single colour stop along a gradient, at `offset` in `[0, 1]`.\n\
         #[derive(Clone, Copy, Debug, PartialEq)]\n\
         pub struct GradientStop {\n\
         \x20   pub offset: f64,\n\
         \x20   pub color: Color,\n\
         }\n\n\
         impl GradientStop {\n\
         \x20   pub const fn new(offset: f64, color: Color) -> Self {\n\
         \x20       Self { offset, color }\n\
         \x20   }\n\n\
         \x20   fn to_abi(self) -> sys::AvnGradientStop {\n\
         \x20       sys::AvnGradientStop { offset: self.offset, color: self.color.into() }\n\
         \x20   }\n\n\
         \x20   fn from_abi(value: sys::AvnGradientStop) -> Self {\n\
         \x20       Self { offset: value.offset, color: value.color.into() }\n\
         \x20   }\n\
         }\n\n\
         /// Packs up to the ABI's fixed capacity of stops into an `AvnGradientStopBuffer`.\n\
         /// Fails if `stops` carries more entries than the buffer can hold.\n\
         fn gradient_stops_to_abi(stops: &[GradientStop]) -> Result<sys::AvnGradientStopBuffer> {\n\
         \x20   let mut buffer = sys::AvnGradientStopBuffer::default();\n\
         \x20   if stops.len() > buffer.stops.len() {\n\
         \x20       return Err(crate::Error::Abi(sys::Error(sys::E_INVALIDARG)));\n\
         \x20   }\n\
         \x20   for (slot, stop) in buffer.stops.iter_mut().zip(stops) {\n\
         \x20       *slot = stop.to_abi();\n\
         \x20   }\n\
         \x20   Ok(buffer)\n\
         }\n\n\
         fn gradient_stops_from_abi(buffer: sys::AvnGradientStopBuffer, count: i32) -> Vec<GradientStop> {\n\
         \x20   let count = usize::try_from(count).unwrap_or(0).min(buffer.stops.len());\n\
         \x20   buffer.stops[..count].iter().copied().map(GradientStop::from_abi).collect()\n\
         }\n\n\
         /// A linear gradient brush: colour stops interpolated along a line from\n\
         /// `start_point` to `end_point`.\n\
         #[derive(Clone, Debug, PartialEq)]\n\
         pub struct LinearGradientBrush {\n\
         \x20   pub opacity: f64,\n\
         \x20   pub spread_method: SpreadMethod,\n\
         \x20   pub stops: Vec<GradientStop>,\n\
         \x20   pub start_point: RelativePoint,\n\
         \x20   pub end_point: RelativePoint,\n\
         }\n\n\
         impl LinearGradientBrush {\n\
         \x20   /// A fully opaque linear gradient with `SpreadMethod::Pad`.\n\
         \x20   pub fn new(stops: Vec<GradientStop>, start_point: RelativePoint, end_point: RelativePoint) -> Self {\n\
         \x20       Self {\n\
         \x20           opacity: 1.0,\n\
         \x20           spread_method: SpreadMethod::Pad,\n\
         \x20           stops,\n\
         \x20           start_point,\n\
         \x20           end_point,\n\
         \x20       }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn to_raw(&self) -> Result<sys::ComPtr<sys::IAvnLinearGradientBrush>> {\n\
         \x20       let buffer = gradient_stops_to_abi(&self.stops)?;\n\
         \x20       let stop_count = i32::try_from(self.stops.len()).unwrap_or(i32::MAX);\n\
         \x20       with_factory(|factory| {\n\
         \x20           factory.create_linear_gradient_brush(\n\
         \x20               self.opacity,\n\
         \x20               self.spread_method as i32,\n\
         \x20               stop_count,\n\
         \x20               buffer,\n\
         \x20               self.start_point.to_abi(),\n\
         \x20               self.end_point.to_abi(),\n\
         \x20           )\n\
         \x20       })\n\
         \x20   }\n\n\
         \x20   pub(crate) fn from_raw(raw: &sys::ComPtr<sys::IAvnLinearGradientBrush>) -> Result<Self> {\n\
         \x20       let count = raw.stop_count()?;\n\
         \x20       Ok(Self {\n\
         \x20           opacity: raw.opacity()?,\n\
         \x20           spread_method: SpreadMethod::try_from(raw.spread_method()?)?,\n\
         \x20           stops: gradient_stops_from_abi(raw.stops()?, count),\n\
         \x20           start_point: RelativePoint::from_abi(raw.start_point()?)?,\n\
         \x20           end_point: RelativePoint::from_abi(raw.end_point()?)?,\n\
         \x20       })\n\
         \x20   }\n\
         }\n\n\
         /// A radial gradient brush: colour stops interpolated outward from\n\
         /// `gradient_origin` through an ellipse centred at `center` with radii\n\
         /// `radius_x`/`radius_y`.\n\
         #[derive(Clone, Debug, PartialEq)]\n\
         pub struct RadialGradientBrush {\n\
         \x20   pub opacity: f64,\n\
         \x20   pub spread_method: SpreadMethod,\n\
         \x20   pub stops: Vec<GradientStop>,\n\
         \x20   pub center: RelativePoint,\n\
         \x20   pub gradient_origin: RelativePoint,\n\
         \x20   pub radius_x: RelativeScalar,\n\
         \x20   pub radius_y: RelativeScalar,\n\
         }\n\n\
         impl RadialGradientBrush {\n\
         \x20   /// A fully opaque radial gradient with `SpreadMethod::Pad`.\n\
         \x20   pub fn new(\n\
         \x20       stops: Vec<GradientStop>,\n\
         \x20       center: RelativePoint,\n\
         \x20       gradient_origin: RelativePoint,\n\
         \x20       radius_x: RelativeScalar,\n\
         \x20       radius_y: RelativeScalar,\n\
         \x20   ) -> Self {\n\
         \x20       Self {\n\
         \x20           opacity: 1.0,\n\
         \x20           spread_method: SpreadMethod::Pad,\n\
         \x20           stops,\n\
         \x20           center,\n\
         \x20           gradient_origin,\n\
         \x20           radius_x,\n\
         \x20           radius_y,\n\
         \x20       }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn to_raw(&self) -> Result<sys::ComPtr<sys::IAvnRadialGradientBrush>> {\n\
         \x20       let buffer = gradient_stops_to_abi(&self.stops)?;\n\
         \x20       let stop_count = i32::try_from(self.stops.len()).unwrap_or(i32::MAX);\n\
         \x20       with_factory(|factory| {\n\
         \x20           factory.create_radial_gradient_brush(\n\
         \x20               self.opacity,\n\
         \x20               self.spread_method as i32,\n\
         \x20               stop_count,\n\
         \x20               buffer,\n\
         \x20               self.center.to_abi(),\n\
         \x20               self.gradient_origin.to_abi(),\n\
         \x20               self.radius_x.to_abi(),\n\
         \x20               self.radius_y.to_abi(),\n\
         \x20           )\n\
         \x20       })\n\
         \x20   }\n\n\
         \x20   pub(crate) fn from_raw(raw: &sys::ComPtr<sys::IAvnRadialGradientBrush>) -> Result<Self> {\n\
         \x20       let count = raw.stop_count()?;\n\
         \x20       Ok(Self {\n\
         \x20           opacity: raw.opacity()?,\n\
         \x20           spread_method: SpreadMethod::try_from(raw.spread_method()?)?,\n\
         \x20           stops: gradient_stops_from_abi(raw.stops()?, count),\n\
         \x20           center: RelativePoint::from_abi(raw.center()?)?,\n\
         \x20           gradient_origin: RelativePoint::from_abi(raw.gradient_origin()?)?,\n\
         \x20           radius_x: RelativeScalar::from_abi(raw.radius_x()?)?,\n\
         \x20           radius_y: RelativeScalar::from_abi(raw.radius_y()?)?,\n\
         \x20       })\n\
         \x20   }\n\
         }\n\n\
         /// Any brush shape that can be assigned to a `Brush`-typed control property: a\n\
         /// solid colour, or one of the two projected gradient shapes.\n\
         #[derive(Clone, Debug, PartialEq)]\n\
         pub enum Paint {\n\
         \x20   Solid(Brush),\n\
         \x20   LinearGradient(LinearGradientBrush),\n\
         \x20   RadialGradient(RadialGradientBrush),\n\
         }\n\n\
         impl Paint {\n\
         \x20   pub(crate) fn to_raw(&self) -> Result<sys::ComPtr<sys::IAvnBrush>> {\n\
         \x20       match self {\n\
         \x20           Self::Solid(brush) => brush.to_raw(),\n\
         \x20           Self::LinearGradient(brush) => Ok(brush.to_raw()?.query_interface()?),\n\
         \x20           Self::RadialGradient(brush) => Ok(brush.to_raw()?.query_interface()?),\n\
         \x20       }\n\
         \x20   }\n\n\
         \x20   pub(crate) fn from_raw(raw: &sys::ComPtr<sys::IAvnBrush>) -> Result<Self> {\n\
         \x20       match raw.color() {\n\
         \x20           Ok(color) => Ok(Self::Solid(Brush::new(color.into(), raw.opacity()?))),\n\
         \x20           Err(sys::Error(sys::AVN_E_NONSOLIDBRUSH)) => {\n\
         \x20               if let Ok(linear) = raw.query_interface::<sys::IAvnLinearGradientBrush>() {\n\
         \x20                   return Ok(Self::LinearGradient(LinearGradientBrush::from_raw(&linear)?));\n\
         \x20               }\n\
         \x20               if let Ok(radial) = raw.query_interface::<sys::IAvnRadialGradientBrush>() {\n\
         \x20                   return Ok(Self::RadialGradient(RadialGradientBrush::from_raw(&radial)?));\n\
         \x20               }\n\
         \x20               Err(crate::Error::Abi(sys::Error(sys::AVN_E_NONSOLIDBRUSH)))\n\
         \x20           }\n\
         \x20           Err(error) => Err(error.into()),\n\
         \x20       }\n\
         \x20   }\n\
         }\n\n\
         impl From<Brush> for Paint {\n\
         \x20   fn from(brush: Brush) -> Self {\n\
         \x20       Self::Solid(brush)\n\
         \x20   }\n\
         }\n\n\
         impl From<Color> for Paint {\n\
         \x20   fn from(color: Color) -> Self {\n\
         \x20       Self::Solid(Brush::solid(color))\n\
         \x20   }\n\
         }\n\n\
         impl From<(u8, u8, u8)> for Paint {\n\
         \x20   fn from((r, g, b): (u8, u8, u8)) -> Self {\n\
         \x20       Self::Solid(Brush::solid(Color::rgb(r, g, b)))\n\
         \x20   }\n\
         }\n\n\
         impl From<LinearGradientBrush> for Paint {\n\
         \x20   fn from(brush: LinearGradientBrush) -> Self {\n\
         \x20       Self::LinearGradient(brush)\n\
         \x20   }\n\
         }\n\n\
         impl From<RadialGradientBrush> for Paint {\n\
         \x20   fn from(brush: RadialGradientBrush) -> Self {\n\
         \x20       Self::RadialGradient(brush)\n\
         \x20   }\n\
         }\n\n",
    )
}

fn emit_flags_struct(
    projected_enum: &crate::ir::ProjectedEnum,
    values: &[&crate::ir::ProjectedEnumValue],
) -> String {
    let name = &projected_enum.name;
    let mut out = format!(
        "/// Bitflags wrapper for `{}`.\n\
         #[repr(transparent)]\n\
         #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]\n\
         pub struct {name}(i32);\n\n\
         impl {name} {{\n",
        projected_enum.full_name
    );
    if !values.iter().any(|v| v.name.eq_ignore_ascii_case("none")) {
        out.push_str("    pub const NONE: Self = Self(0);\n");
    }
    for value in values {
        out.push_str(&format!(
            "    pub const {}: Self = Self({});\n",
            to_shouty_snake(&value.name),
            value.value
        ));
    }
    out.push_str(
        "    pub const fn bits(self) -> i32 { self.0 }\n\
         \x20   pub const fn from_bits_retain(bits: i32) -> Self { Self(bits) }\n\
         \x20   pub const fn is_empty(self) -> bool { self.0 == 0 }\n\
         \x20   pub const fn contains(self, other: Self) -> bool { (self.0 & other.0) == other.0 }\n\
         }\n\n",
    );
    out.push_str(&format!(
        "impl std::ops::BitOr for {name} {{\n\
         \x20   type Output = Self;\n\
         \x20   fn bitor(self, rhs: Self) -> Self {{ Self(self.0 | rhs.0) }}\n\
         }}\n\
         impl std::ops::BitOrAssign for {name} {{\n\
         \x20   fn bitor_assign(&mut self, rhs: Self) {{ self.0 |= rhs.0; }}\n\
         }}\n\
         impl std::ops::BitAnd for {name} {{\n\
         \x20   type Output = Self;\n\
         \x20   fn bitand(self, rhs: Self) -> Self {{ Self(self.0 & rhs.0) }}\n\
         }}\n\
         impl std::ops::BitAndAssign for {name} {{\n\
         \x20   fn bitand_assign(&mut self, rhs: Self) {{ self.0 &= rhs.0; }}\n\
         }}\n\
         impl std::ops::BitXor for {name} {{\n\
         \x20   type Output = Self;\n\
         \x20   fn bitxor(self, rhs: Self) -> Self {{ Self(self.0 ^ rhs.0) }}\n\
         }}\n\
         impl std::ops::Not for {name} {{\n\
         \x20   type Output = Self;\n\
         \x20   fn not(self) -> Self {{ Self(!self.0) }}\n\
         }}\n\n"
    ));
    out
}

fn to_shouty_snake(name: &str) -> String {
    to_snake(name).to_ascii_uppercase()
}

fn emit_safe_event_types(
    ir: &ProjectionIr,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    let mut out = String::new();
    let mut emitted_args = std::collections::HashSet::new();
    let mut emitted_fields = std::collections::HashSet::new();

    for event in ir.types.iter().flat_map(|ty| ty.events.iter()) {
        if event.payload_kind == "Args" {
            let raw_name = simple_name(
                event
                    .args_interface_name
                    .as_deref()
                    .expect("argsInterfaceName"),
            );
            if !emitted_args.insert(raw_name.to_string()) {
                continue;
            }
            let safe_name = interface_suffix(raw_name);
            out.push_str(&format!(
                "#[derive(Clone, Debug, PartialEq)]\n\
                 pub struct {safe_name} {{\n"
            ));
            for param in &event.parameters {
                out.push_str(&format!(
                    "    pub {}: Vec<Variant>,\n",
                    to_snake(&param.name)
                ));
            }
            out.push_str("}\n\n");
            out.push_str(&format!(
                "impl {safe_name} {{\n\
                 \x20   pub(crate) fn from_raw(raw: &sys::ComPtr<sys::{raw_name}>) -> sys::Result<Self> {{\n"
            ));
            for param in &event.parameters {
                let p = to_snake(&param.name);
                out.push_str(&format!(
                    "        let {p}_len = raw.{p}_count()?.max(0);\n\
                     \x20       let mut {p} = Vec::with_capacity({p}_len as usize);\n\
                     \x20       for index in 0..{p}_len {{\n\
                     \x20           {p}.push(Variant::from_abi(raw.{p}_at(index)?));\n\
                     \x20       }}\n"
                ));
            }
            out.push_str("        Ok(Self {\n");
            for param in &event.parameters {
                out.push_str(&format!("            {},\n", to_snake(&param.name)));
            }
            out.push_str("        })\n    }\n}\n\n");
        } else if !event.parameters.is_empty() {
            let args_name = event_arguments_name(event);
            if !emitted_fields.insert(args_name.clone()) {
                continue;
            }
            out.push_str(&format!(
                "#[derive(Clone, Debug, PartialEq)]\n\
                 pub struct {args_name} {{\n"
            ));
            for param in &event.parameters {
                let field = to_snake(&param.name);
                let ty = safe_event_field_type(param, flags_enums, regular_enums);
                out.push_str(&format!("    pub {field}: {ty},\n"));
            }
            out.push_str("}\n\n");
            out.push_str(&format!(
                "impl {args_name} {{\n\
                 \x20   pub(crate) fn from_sys(raw: &sys::{args_name}) -> sys::Result<Self> {{\n\
                 \x20       Ok(Self {{\n"
            ));
            for param in &event.parameters {
                let field = to_snake(&param.name);
                let conv = safe_event_field_from_sys(&field, param, flags_enums, regular_enums);
                out.push_str(&format!("            {field}: {conv},\n"));
            }
            out.push_str("        })\n    }\n");
            out.push_str(&format!(
                "    pub(crate) fn write_back(&self, _raw: &mut sys::{args_name}) {{\n"
            ));
            for param in event.parameters.iter().filter(|p| p.direction == "InOut") {
                let field = to_snake(&param.name);
                let wb = safe_event_field_write_back(&field, param, flags_enums, regular_enums);
                out.push_str(&format!("        _raw.{field} = {wb};\n"));
            }
            out.push_str("    }\n}\n\n");
        }
    }
    out
}

fn safe_event_field_type(
    param: &crate::ir::ProjectedParameter,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    if let Some(geometry) = geometry::find(&param.kind) {
        return if param.is_nullable {
            format!("Option<{}>", geometry.safe_name)
        } else {
            geometry.safe_name.to_string()
        };
    }
    match param.kind.as_str() {
        "Bool" => "bool".to_string(),
        "I32" => {
            if let Some(m) = param.managed_type_name.as_deref() {
                if flags_enums.contains(m) || regular_enums.contains(m) {
                    return simple_name(m).to_string();
                }
            }
            "i32".to_string()
        }
        "StringUtf16" => {
            if param
                .managed_type_name
                .as_deref()
                .is_some_and(|m| m.contains("System.Decimal"))
            {
                if param.is_nullable {
                    "Option<crate::Decimal>".to_string()
                } else {
                    "crate::Decimal".to_string()
                }
            } else if param.is_nullable {
                "Option<String>".to_string()
            } else {
                "String".to_string()
            }
        }
        "DateTimeI64" => {
            if param.is_nullable {
                "Option<std::time::SystemTime>".to_string()
            } else {
                "std::time::SystemTime".to_string()
            }
        }
        "TimeSpanI64" => {
            if param.is_nullable {
                "Option<std::time::Duration>".to_string()
            } else {
                "std::time::Duration".to_string()
            }
        }
        "Variant" => "Variant".to_string(),
        other => rust_scalar_kind(other).to_string(),
    }
}

fn safe_event_field_from_sys(
    field: &str,
    param: &crate::ir::ProjectedParameter,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    if let Some(geometry) = geometry::find(&param.kind) {
        return if param.is_nullable {
            format!("{}::from_optional_abi(raw.{field})", geometry.safe_name)
        } else {
            format!("raw.{field}.into()")
        };
    }
    match param.kind.as_str() {
        "I32" => {
            if let Some(m) = param.managed_type_name.as_deref() {
                let name = simple_name(m);
                if flags_enums.contains(m) {
                    return format!("{name}::from_bits_retain(raw.{field})");
                }
                if regular_enums.contains(m) {
                    return format!(
                        "{name}::try_from(raw.{field}).map_err(|_| sys::Error(sys::E_INVALIDARG))?"
                    );
                }
            }
            format!("raw.{field}")
        }
        "StringUtf16" => {
            if param
                .managed_type_name
                .as_deref()
                .is_some_and(|m| m.contains("System.Decimal"))
            {
                if param.is_nullable {
                    format!(
                        "raw.{field}.as_deref().filter(|s| !s.is_empty()).map(crate::Decimal::from_abi_str).transpose().map_err(|_| sys::Error(sys::E_INVALIDARG))?"
                    )
                } else {
                    format!(
                        "crate::Decimal::from_abi_str(&raw.{field}).map_err(|_| sys::Error(sys::E_INVALIDARG))?"
                    )
                }
            } else {
                format!("raw.{field}.clone()")
            }
        }
        "DateTimeI64" => {
            if param.is_nullable {
                format!("raw.{field}.try_to_date_time()?")
            } else {
                format!(
                    "{{ let u = raw.{field} - sys::DOTNET_EPOCH_OFFSET_TICKS; std::time::UNIX_EPOCH + std::time::Duration::from_nanos((u.clamp(0, i64::MAX) as u64) * 100) }}"
                )
            }
        }
        "TimeSpanI64" => {
            if param.is_nullable {
                format!("raw.{field}.try_to_duration()?")
            } else {
                format!("std::time::Duration::from_nanos((raw.{field}.clamp(0, i64::MAX / 100) as u64) * 100)")
            }
        }
        "Variant" => format!("unsafe {{ Variant::from_borrowed_abi(raw.{field})? }}"),
        _ => format!("raw.{field}"),
    }
}

fn safe_event_field_write_back(
    field: &str,
    param: &crate::ir::ProjectedParameter,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    if param.kind == "I32" {
        if let Some(m) = param.managed_type_name.as_deref() {
            if flags_enums.contains(m) {
                return format!("self.{field}.bits()");
            }
            if regular_enums.contains(m) {
                return format!("self.{field} as i32");
            }
        }
    }
    format!("self.{field}")
}

fn emit_collection(property: &ProjectedProperty) -> String {
    let name = simple_name(property.interface_name.as_deref().expect("interfaceName"));
    let safe_name = name.strip_prefix("IAvn").unwrap_or(name);
    let mut out = format!(
        "#[derive(Clone, Debug)]\n\
         pub struct {safe_name} {{\n\
         \x20   pub(crate) raw: sys::ComPtr<sys::{name}>,\n\
         }}\n\n"
    );
    out.push_str(&format!(
        "impl {safe_name} {{\n\
         \x20   pub fn len(&self) -> Result<usize> {{ Ok(self.raw.len()?) }}\n\
         \x20   pub fn is_empty(&self) -> Result<bool> {{ Ok(self.len()? == 0) }}\n"
    ));
    match property.element_kind.as_deref() {
        Some("ComInterface") => {
            let element = simple_name(
                property
                    .element_interface_name
                    .as_deref()
                    .expect("elementInterfaceName"),
            )
            .strip_prefix("IAvn")
            .unwrap();
            out.push_str(&format!(
                "    pub fn get(&self, index: usize) -> Result<{element}> {{\n\
                 \x20       Ok({element} {{ raw: self.raw.get(index)? }})\n\
                 \x20   }}\n\
                 \x20   pub fn add(&self, value: impl As{element}) -> Result<()> {{\n\
                 \x20       let value = value.as_{element_snake}()?;\n\
                 \x20       Ok(self.raw.add(&value)?)\n\
                 \x20   }}\n\
                 \x20   pub fn insert(&self, index: usize, value: impl As{element}) -> Result<()> {{\n\
                 \x20       let value = value.as_{element_snake}()?;\n\
                 \x20       Ok(self.raw.insert(index, &value)?)\n\
                 \x20   }}\n\
                 \x20   pub fn index_of(&self, value: impl As{element}) -> Result<Option<usize>> {{\n\
                 \x20       let value = value.as_{element_snake}()?;\n\
                 \x20       Ok(self.raw.index_of(&value)?)\n\
                 \x20   }}\n",
                element_snake = to_snake(element)
            ));
        }
        Some("StringUtf16") => out.push_str(
            "    pub fn get(&self, index: usize) -> Result<String> {\n\
             \x20       unsafe { sys::take_utf16(self.raw.get(index)?).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER))) }\n\
             \x20   }\n\
             \x20   pub fn add(&self, value: impl AsRef<str>) -> Result<()> {\n\
             \x20       let value: Vec<u16> = value.as_ref().encode_utf16().chain(Some(0)).collect();\n\
             \x20       Ok(self.raw.add(&value)?)\n\
             \x20   }\n\
             \x20   pub fn insert(&self, index: usize, value: impl AsRef<str>) -> Result<()> {\n\
             \x20       let value: Vec<u16> = value.as_ref().encode_utf16().chain(Some(0)).collect();\n\
             \x20       Ok(self.raw.insert(index, &value)?)\n\
             \x20   }\n\
             \x20   pub fn contains(&self, value: impl AsRef<str>) -> Result<bool> {\n\
             \x20       let value: Vec<u16> = value.as_ref().encode_utf16().chain(Some(0)).collect();\n\
             \x20       Ok(self.raw.index_of(&value)?.is_some())\n\
             \x20   }\n\
             \x20   pub fn remove_value(&self, value: impl AsRef<str>) -> Result<bool> {\n\
             \x20       let value: Vec<u16> = value.as_ref().encode_utf16().chain(Some(0)).collect();\n\
             \x20       if let Some(index) = self.raw.index_of(&value)? {\n\
             \x20           self.raw.remove(index)?;\n\
             \x20           Ok(true)\n\
             \x20       } else {\n\
             \x20           Ok(false)\n\
             \x20       }\n\
             \x20   }\n",
        ),
        Some("Variant") => out.push_str(
            "    pub fn get(&self, index: usize) -> Result<Variant> {\n\
             \x20       Ok(Variant::from_abi(self.raw.get(index)?))\n\
             \x20   }\n\
             \x20   pub fn add(&self, value: impl Into<Variant>) -> Result<()> {\n\
             \x20       let value = value.into().to_abi()?;\n\
             \x20       Ok(self.raw.add(*value)?)\n\
             \x20   }\n\
             \x20   pub fn insert(&self, index: usize, value: impl Into<Variant>) -> Result<()> {\n\
             \x20       let value = value.into().to_abi()?;\n\
             \x20       Ok(self.raw.insert(index, *value)?)\n\
             \x20   }\n\
             \x20   pub fn contains(&self, value: impl Into<Variant>) -> Result<bool> {\n\
             \x20       let value = value.into().to_abi()?;\n\
             \x20       Ok(self.raw.index_of(*value)?.is_some())\n\
             \x20   }\n",
        ),
        Some("DateTimeI64") => out.push_str(
            "    pub fn get(&self, index: usize) -> Result<std::time::SystemTime> {\n\
             \x20       let ticks = self.raw.get(index)?;\n\
             \x20       let unix_ticks = ticks - sys::DOTNET_EPOCH_OFFSET_TICKS;\n\
             \x20       let nanos = (unix_ticks.clamp(0, i64::MAX) as u128) * 100;\n\
             \x20       Ok(std::time::UNIX_EPOCH + std::time::Duration::from_nanos(nanos as u64))\n\
             \x20   }\n\
             \x20   pub fn add(&self, value: std::time::SystemTime) -> Result<()> {\n\
             \x20       let ticks = value\n\
             \x20           .duration_since(std::time::UNIX_EPOCH)\n\
             \x20           .map(|delta| delta.as_nanos() / 100)\n\
             \x20           .unwrap_or(0) as i64;\n\
             \x20       Ok(self.raw.add(ticks + sys::DOTNET_EPOCH_OFFSET_TICKS)?)\n\
             \x20   }\n\
             \x20   pub fn insert(&self, index: usize, value: std::time::SystemTime) -> Result<()> {\n\
             \x20       let ticks = value\n\
             \x20           .duration_since(std::time::UNIX_EPOCH)\n\
             \x20           .map(|delta| delta.as_nanos() / 100)\n\
             \x20           .unwrap_or(0) as i64;\n\
             \x20       Ok(self.raw.insert(index, ticks + sys::DOTNET_EPOCH_OFFSET_TICKS)?)\n\
             \x20   }\n\
             \x20   pub fn contains(&self, value: std::time::SystemTime) -> Result<bool> {\n\
             \x20       let ticks = value\n\
             \x20           .duration_since(std::time::UNIX_EPOCH)\n\
             \x20           .map(|delta| delta.as_nanos() / 100)\n\
             \x20           .unwrap_or(0) as i64;\n\
             \x20       Ok(self.raw.index_of(ticks + sys::DOTNET_EPOCH_OFFSET_TICKS)?.is_some())\n\
             \x20   }\n",
        ),
        kind => panic!("unsupported safe collection element kind {kind:?}"),
    }
    out.push_str(
        "    pub fn remove(&self, index: usize) -> Result<()> { Ok(self.raw.remove(index)?) }\n\
         \x20   pub fn clear(&self) -> Result<()> { Ok(self.raw.clear()?) }\n\
         }\n",
    );
    out
}

fn emit_type(
    ir: &ProjectionIr,
    ty: &ProjectedType,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    let safe_name = interface_suffix(&ty.name);
    let has_text_block = ir
        .types
        .iter()
        .any(|candidate| candidate.name == "IAvnTextBlock" && candidate.is_constructible);
    let mut out = format!(
        "#[repr(transparent)]\n\
         #[derive(Clone, Debug)]\n\
         pub struct {safe_name} {{\n\
         \x20   pub(crate) raw: sys::ComPtr<sys::{interface_name}>,\n\
         }}\n\n\
         impl {safe_name} {{\n",
        interface_name = ty.name
    );

    if ty.is_constructible {
        out.push_str(&format!(
            "    pub fn new() -> Result<Self> {{\n\
             \x20       with_factory(|factory| factory.create_{factory_name}())\n\
             \x20           .map(|raw| Self {{ raw }})\n\
             \x20   }}\n",
            factory_name = to_snake(safe_name)
        ));
        if has_text_block {
            out.push_str(
                "    pub fn el() -> crate::view::El<Self> {\n\
                 \x20       crate::view::El::new(Self::new)\n\
                 \x20   }\n",
            );
        }
    }
    if has_text_block {
        out.push_str(
            "    pub fn object_id(&self) -> Result<i64> {\n\
             \x20       Ok(self.raw.object_id()?)\n\
             \x20   }\n\
             \x20   pub fn same_object(&self, other: &impl crate::Upcast<AvaloniaObject>) -> Result<bool> {\n\
             \x20       Ok(self.raw.object_id()? == other.upcast_ref().raw.object_id()?)\n\
             \x20   }\n\
             \x20   pub fn is<Target>(&self) -> bool\n\
             \x20   where\n\
             \x20       Self: crate::Downcast<Target>,\n\
             \x20   {\n\
             \x20       <Self as crate::Downcast<Target>>::is_instance(self)\n\
             \x20   }\n\
             \x20   pub fn cast<Target>(&self) -> Option<Target>\n\
             \x20   where\n\
             \x20       Self: crate::Downcast<Target>,\n\
             \x20   {\n\
             \x20       <Self as crate::Downcast<Target>>::downcast(self)\n\
             \x20   }\n",
        );
    }

    let reserved_methods: std::collections::HashSet<String> = lineage(ir, ty)
        .iter()
        .flat_map(|owner| owner.methods.iter().map(|method| to_snake(&method.name)))
        .collect();
    for owner in lineage(ir, ty) {
        for property in &owner.properties {
            out.push_str(&emit_property(
                property,
                &reserved_methods,
                flags_enums,
                regular_enums,
            ));
            if has_text_block
                && property.can_write
                && property.kind == "ComInterface"
                && property.interface_name.as_deref().map(simple_name) == Some("IAvnControl")
            {
                if property.name == "Content" {
                    out.push_str(
                        "    pub fn set_content_text(&self, value: impl AsRef<str>) -> Result<()> {\n\
                         \x20       self.set_content(value.as_ref())\n\
                         \x20   }\n",
                    );
                } else if property.name == "Header" {
                    out.push_str(
                        "    pub fn set_header_text(&self, value: impl AsRef<str>) -> Result<()> {\n\
                         \x20       self.set_header(value.as_ref())\n\
                         \x20   }\n",
                    );
                }
            }
        }
        for method in &owner.methods {
            out.push_str(&emit_method(ty, method, flags_enums, regular_enums));
        }
        for event in &owner.events {
            out.push_str(&emit_event(event));
        }
    }
    for property in ir
        .attached_properties
        .iter()
        .filter(|property| property.owner_name == safe_name)
    {
        out.push_str(&emit_attached_property(
            property,
            ir,
            flags_enums,
            regular_enums,
        ));
    }
    if is_control(ir, ty) {
        for property in &ir.attached_properties {
            out.push_str(&emit_inline_attached_property(
                property,
                ir,
                flags_enums,
                regular_enums,
            ));
        }
    }
    out.push_str("}\n\n");

    if let Some(base_full_name) = &ty.base_full_name {
        let parent = ir
            .types
            .iter()
            .find(|candidate| &candidate.full_name == base_full_name)
            .expect("base type must be present in projection IR");
        let parent_safe = interface_suffix(&parent.name);
        out.push_str(&format!(
            "impl std::ops::Deref for {safe_name} {{\n\
             \x20   type Target = {parent_safe};\n\
             \x20   fn deref(&self) -> &Self::Target {{\n\
             \x20       unsafe {{ &*(self as *const Self as *const Self::Target) }}\n\
             \x20   }}\n\
             }}\n\n"
        ));
    }

    for ancestor in lineage(ir, ty) {
        if ancestor.full_name == ty.full_name {
            continue;
        }
        let ancestor_safe = interface_suffix(&ancestor.name);
        out.push_str(&format!(
            "unsafe impl crate::Upcast<{ancestor_safe}> for {safe_name} {{\n\
             \x20   fn upcast(&self) -> {ancestor_safe} {{\n\
             \x20       {ancestor_safe} {{\n\
             \x20           raw: unsafe {{ self.raw.cast_clone() }},\n\
             \x20       }}\n\
             \x20   }}\n\
             \x20   fn upcast_ref(&self) -> &{ancestor_safe} {{\n\
             \x20       unsafe {{ &*(self as *const Self as *const {ancestor_safe}) }}\n\
             \x20   }}\n\
             }}\n\n\
             impl AsRef<{ancestor_safe}> for {safe_name} {{\n\
             \x20   fn as_ref(&self) -> &{ancestor_safe} {{\n\
             \x20       <Self as crate::Upcast<{ancestor_safe}>>::upcast_ref(self)\n\
             \x20   }}\n\
             }}\n\n\
             unsafe impl crate::Downcast<{safe_name}> for {ancestor_safe} {{\n\
             \x20   fn is_instance(&self) -> bool {{\n\
             \x20       self.raw.query_interface::<sys::{interface_name}>().is_ok()\n\
             \x20   }}\n\
             \x20   fn downcast(&self) -> Option<{safe_name}> {{\n\
             \x20       self.raw\n\
             \x20           .query_interface::<sys::{interface_name}>()\n\
             \x20           .ok()\n\
             \x20           .map(|raw| {safe_name} {{ raw }})\n\
             \x20   }}\n\
             }}\n\n",
            interface_name = ty.name
        ));
    }

    if is_control(ir, ty) {
        if safe_name == "Control" {
            out.push_str(
                "impl AsControl for Control {\n\
                 \x20   fn as_control(&self) -> Result<sys::ComPtr<sys::IAvnControl>> {\n\
                 \x20       Ok(self.raw.clone())\n\
                 \x20   }\n\
                 }\n",
            );
        } else {
            out.push_str(&format!(
                "impl AsControl for {safe_name} {{\n\
                 \x20   fn as_control(&self) -> Result<sys::ComPtr<sys::IAvnControl>> {{\n\
                 \x20       Ok(self.raw.query_interface()?)\n\
                 \x20   }}\n\
                 }}\n"
            ));
        }
    }

    if ty.is_constructible && has_text_block {
        out.push('\n');
        out.push_str(&emit_el_type(
            ir,
            ty,
            &reserved_methods,
            flags_enums,
            regular_enums,
        ));
    }

    fn emit_inline_attached_property(
        property: &crate::ir::ProjectedAttachedProperty,
        ir: &ProjectionIr,
        flags_enums: &std::collections::HashSet<&str>,
        regular_enums: &std::collections::HashSet<&str>,
    ) -> String {
        let owner_type = &property.owner_name;
        let owner = to_snake(owner_type);
        let name = to_snake(&property.name);
        let accessor = attached_accessor_name(property, ir);
        if property.kind == "StringUtf16" {
            let get_type = if property.is_nullable {
                "Option<String>"
            } else {
                "String"
            };
            return format!(
                "    pub fn {owner}_{name}(&self) -> Result<{get_type}> {{\n\
                 \x20       {owner_type}::{accessor}(self)\n\
                 \x20   }}\n\
                 \x20   pub fn set_{owner}_{name}(&self, value: impl AsRef<str>) -> Result<()> {{\n\
                 \x20       {owner_type}::set_{accessor}(self, value)\n\
                 \x20   }}\n"
            );
        }
        let enum_name = simple_name(&property.managed_type_name);
        let is_enum = regular_enums.contains(property.managed_type_name.as_str())
            || flags_enums.contains(property.managed_type_name.as_str());
        let (get_type, set_arg, set_forward) = if is_enum {
            (
                enum_name.to_string(),
                enum_name.to_string(),
                "value".to_string(),
            )
        } else if property.kind == "TimeSpanI64" {
            (
                "std::time::Duration".to_string(),
                "std::time::Duration".to_string(),
                "value".to_string(),
            )
        } else if let Some(geometry) = geometry::find(&property.kind) {
            if property.is_nullable {
                (
                    format!("Option<{}>", geometry.safe_name),
                    format!("impl Into<Option<{}>>", geometry.safe_name),
                    "value.into()".to_string(),
                )
            } else {
                (
                    geometry.safe_name.to_string(),
                    format!("impl Into<{}>", geometry.safe_name),
                    "value.into()".to_string(),
                )
            }
        } else {
            let scalar = rust_scalar_kind(&property.kind).to_string();
            (scalar.clone(), scalar, "value".to_string())
        };
        format!(
            "    pub fn {owner}_{name}(&self) -> Result<{get_type}> {{\n\
             \x20       {owner_type}::{accessor}(self)\n\
             \x20   }}\n\
             \x20   pub fn set_{owner}_{name}(&self, value: {set_arg}) -> Result<()> {{\n\
             \x20       {owner_type}::set_{accessor}(self, {set_forward})\n\
             \x20   }}\n"
        )
    }

    fn emit_attached_property(
        property: &crate::ir::ProjectedAttachedProperty,
        ir: &ProjectionIr,
        flags_enums: &std::collections::HashSet<&str>,
        regular_enums: &std::collections::HashSet<&str>,
    ) -> String {
        let owner = to_snake(&property.owner_name);
        let name = to_snake(&property.name);
        let accessor = attached_accessor_name(property, ir);
        if property.kind == "StringUtf16" {
            let (get_type, get_body) = if property.is_nullable {
                (
                    "Option<String>",
                    "        unsafe { Ok(sys::take_utf16(value)) }",
                )
            } else {
                (
                    "String",
                    "        unsafe { sys::take_utf16(value).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER))) }",
                )
            };
            return format!(
                "    pub fn {accessor}(target: &impl AsControl) -> Result<{get_type}> {{\n\
                 \x20       let target = target.as_control()?;\n\
                 \x20       let value = with_factory(|factory| factory.get_{owner}_statics()?.get_{name}(&target))?;\n\
                 {get_body}\n\
                 \x20   }}\n\
                 \x20   pub fn set_{accessor}(target: &impl AsControl, value: impl AsRef<str>) -> Result<()> {{\n\
                 \x20       let target = target.as_control()?;\n\
                 \x20       let value: Vec<u16> = value.as_ref().encode_utf16().chain(Some(0)).collect();\n\
                 \x20       with_factory(|factory| factory.get_{owner}_statics()?.set_{name}(&target, &value))\n\
                 \x20   }}\n"
            );
        }
        let enum_name = simple_name(&property.managed_type_name);
        let is_flags = flags_enums.contains(property.managed_type_name.as_str());
        let is_regular_enum = regular_enums.contains(property.managed_type_name.as_str());
        let safe_type = if is_flags || is_regular_enum {
            enum_name.to_string()
        } else if property.kind == "TimeSpanI64" {
            "std::time::Duration".to_string()
        } else if let Some(geometry) = geometry::find(&property.kind) {
            if property.is_nullable {
                format!("Option<{}>", geometry.safe_name)
            } else {
                geometry.safe_name.to_string()
            }
        } else {
            rust_scalar_kind(&property.kind).to_string()
        };
        let raw_get = if is_flags {
            format!("Ok({enum_name}::from_bits_retain(value))")
        } else if is_regular_enum {
            format!("{enum_name}::try_from(value)")
        } else if property.kind == "TimeSpanI64" {
            "Ok(std::time::Duration::from_nanos(value.clamp(0, i64::MAX / 100) as u64 * 100))"
                .to_string()
        } else if let Some(geometry) = geometry::find(&property.kind) {
            if property.is_nullable {
                format!("Ok({}::from_optional_abi(value))", geometry.safe_name)
            } else {
                "Ok(value.into())".to_string()
            }
        } else {
            "Ok(value)".to_string()
        };
        let raw_set = if is_flags {
            "value.bits()".to_string()
        } else if is_regular_enum {
            "value as i32".to_string()
        } else if property.kind == "TimeSpanI64" {
            "(value.as_nanos() / 100).clamp(0, i64::MAX as u128) as i64".to_string()
        } else if let Some(geometry) = geometry::find(&property.kind) {
            if property.is_nullable {
                format!("{}::to_optional_abi(value)", geometry.safe_name)
            } else {
                "value.into()".to_string()
            }
        } else {
            "value".to_string()
        };
        format!(
            "    pub fn {accessor}(target: &impl AsControl) -> Result<{safe_type}> {{\n\
             \x20       let target = target.as_control()?;\n\
             \x20       let value = with_factory(|factory| factory.get_{owner}_statics()?.get_{name}(&target))?;\n\
             \x20       {raw_get}\n\
             \x20   }}\n\
             \x20   pub fn set_{accessor}(target: &impl AsControl, value: {safe_type}) -> Result<()> {{\n\
             \x20       let target = target.as_control()?;\n\
             \x20       with_factory(|factory| factory.get_{owner}_statics()?.set_{name}(&target, {raw_set}))\n\
             \x20   }}\n"
        )
    }
    out
}

fn attached_accessor_name(
    property: &crate::ir::ProjectedAttachedProperty,
    ir: &ProjectionIr,
) -> String {
    let name = to_snake(&property.name);
    let owner = format!("IAvn{}", property.owner_name);
    let collision = ir
        .types
        .iter()
        .find(|ty| ty.name == owner)
        .is_some_and(|ty| {
            lineage(ir, ty).iter().any(|ancestor| {
                ancestor
                    .properties
                    .iter()
                    .any(|candidate| candidate.name == property.name)
                    || ancestor.methods.iter().any(|method| {
                        let method = to_snake(&method.name);
                        method == name
                            || method == format!("get_{name}")
                            || method == format!("set_{name}")
                    })
            })
        });
    if collision {
        format!("attached_{name}")
    } else {
        escape_ident(&name)
    }
}

fn emit_el_type(
    ir: &ProjectionIr,
    ty: &ProjectedType,
    reserved_methods: &std::collections::HashSet<String>,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    let safe_name = interface_suffix(&ty.name);
    let mut out = format!("impl crate::view::El<{safe_name}> {{\n");
    let all_events: Vec<&ProjectedEvent> = lineage(ir, ty)
        .into_iter()
        .flat_map(|owner| owner.events.iter())
        .collect();
    let has_event = |name: &str| all_events.iter().any(|event| event.name == name);
    let all_props: Vec<&ProjectedProperty> = lineage(ir, ty)
        .into_iter()
        .flat_map(|owner| owner.properties.iter())
        .collect();

    for owner in lineage(ir, ty) {
        for property in &owner.properties {
            let snake = to_snake(&property.name);
            let builder_raw = if property.kind == "Bool" || property.kind == "NullableBool" {
                match snake.strip_prefix("is_") {
                    Some(stripped) if !reserved_methods.contains(stripped) => stripped,
                    _ => snake.as_str(),
                }
            } else {
                snake.as_str()
            };
            let builder = escape_ident(builder_raw);
            let getter = getter_name(&snake, reserved_methods);

            if property.kind == "ComCollection" && property.name == "Children" {
                out.push_str(
                    "    pub fn child(self, value: impl crate::view::IntoChildEl + 'static) -> Self {\n\
                     \x20       self.with_op(move |scope, control| {\n\
                     \x20           let built = value.into_child_el().build(scope)?;\n\
                     \x20           control.children()?.add(built)\n\
                     \x20       })\n\
                     \x20   }\n\
                     \x20   pub fn children_iter<I, C>(mut self, children: I) -> Self\n\
                     \x20   where\n\
                     \x20       I: IntoIterator<Item = C>,\n\
                     \x20       C: crate::view::IntoChildEl + 'static,\n\
                     \x20   {\n\
                     \x20       for child in children {\n\
                     \x20           self = self.child(child);\n\
                     \x20       }\n\
                     \x20       self\n\
                     \x20   }\n",
                );
            }
            if property.kind == "ComCollection" && property.name == "Items" {
                out.push_str(
                    "    pub fn item(self, value: impl crate::view::IntoChildEl + 'static) -> Self {\n\
                     \x20       self.with_op(move |scope, control| {\n\
                     \x20           let built = value.into_child_el().build(scope)?;\n\
                     \x20           control.items()?.add(built)\n\
                     \x20       })\n\
                     \x20   }\n\
                     \x20   pub fn items_iter<I, C>(mut self, items: I) -> Self\n\
                     \x20   where\n\
                     \x20       I: IntoIterator<Item = C>,\n\
                     \x20       C: crate::view::IntoChildEl + 'static,\n\
                     \x20   {\n\
                     \x20       for item in items {\n\
                     \x20           self = self.item(item);\n\
                     \x20       }\n\
                     \x20       self\n\
                     \x20   }\n",
                );
            }

            if !property.can_write {
                continue;
            }

            match property.kind.as_str() {
                "ComInterface" => {
                    let safe = interface_suffix(simple_name(
                        property.interface_name.as_deref().expect("interfaceName"),
                    ));
                    if safe == "Control" {
                        if property.is_nullable {
                            out.push_str(&format!(
                                "    pub fn {builder}(self, value: impl crate::view::IntoContentEl + 'static) -> Self {{\n\
                                 \x20       self.with_op(move |scope, control| {{\n\
                                 \x20           let built = value.into_content_el().map(|el| el.build(scope)).transpose()?;\n\
                                 \x20           control.set_{builder_raw}(built)\n\
                                 \x20       }})\n\
                                 \x20   }}\n"
                            ));
                        } else {
                            out.push_str(&format!(
                                "    pub fn {builder}(self, value: impl crate::view::IntoChildEl + 'static) -> Self {{\n\
                                 \x20       self.with_op(move |scope, control| {{\n\
                                 \x20           let built = value.into_child_el().build(scope)?;\n\
                                 \x20           control.set_{builder_raw}(built)\n\
                                 \x20       }})\n\
                                 \x20   }}\n"
                            ));
                        }
                    } else if property.is_nullable {
                        out.push_str(&format!(
                            "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<Option<{safe}>, M> + 'static) -> Self {{\n\
                             \x20       let binding = value.into_prop();\n\
                             \x20       self.with_op(move |_, control| {{\n\
                             \x20           crate::view::apply_prop(control, binding, |c, v| c.set_{builder_raw}(v.as_ref()))\n\
                             \x20       }})\n\
                             \x20   }}\n"
                        ));
                    } else {
                        out.push_str(&format!(
                            "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<{safe}, M> + 'static) -> Self {{\n\
                             \x20       let binding = value.into_prop();\n\
                             \x20       self.with_op(move |_, control| {{\n\
                             \x20           crate::view::apply_prop(control, binding, |c, v| c.set_{builder_raw}(&v))\n\
                             \x20       }})\n\
                             \x20   }}\n"
                        ));
                    }
                }
                "ComCollection" => {}
                "DataTemplate" => {
                    out.push_str(&format!(
                        "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<Option<DataTemplate>, M> + 'static) -> Self {{\n\
                         \x20       let binding = value.into_prop();\n\
                         \x20       self.with_op(move |_, control| {{\n\
                         \x20           crate::view::apply_prop(control, binding, |c, v| c.set_{builder_raw}(v.as_ref()))\n\
                         \x20       }})\n\
                         \x20   }}\n"
                    ));
                }
                "Command" => {
                    out.push_str(&format!(
                        "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<Option<crate::Command>, M> + 'static) -> Self {{\n\
                         \x20       let binding = value.into_prop();\n\
                         \x20       self.with_op(move |_, control| {{\n\
                         \x20           crate::view::apply_prop(control, binding, |c, v| c.set_{builder_raw}(v))\n\
                         \x20       }})\n\
                         \x20   }}\n"
                    ));
                }
                "ItemFilter" | "TextFilter" | "ItemSelector" | "TextSelector"
                | "PopupPlacement" | "AsyncPopulator" => {
                    let cb_type = safe_callback_type(&property.kind);
                    out.push_str(&format!(
                        "    pub fn {builder}(self, value: impl Into<Option<{cb_type}>> + 'static) -> Self {{\n\
                         \x20       let value = value.into();\n\
                         \x20       self.with_op(move |_, control| control.set_{builder_raw}(value.as_ref()))\n\
                         \x20   }}\n"
                    ));
                }
                _ => {
                    let prop_type = el_prop_type(property, flags_enums, regular_enums);
                    let set_call = el_setter_expr(property, builder_raw);

                    if let Some(spec) = el_two_way_spec(property, &getter, has_event) {
                        match spec {
                            TwoWaySpec::Single { get_expr, event } => {
                                out.push_str(&format!(
                                    "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<{prop_type}, M> + 'static) -> Self {{\n\
                                     \x20       let binding = value.into_prop();\n\
                                     \x20       self.with_op(move |scope, control| {{\n\
                                     \x20           crate::view::apply_two_way_prop(\n\
                                     \x20               scope,\n\
                                     \x20               control,\n\
                                     \x20               binding,\n\
                                     \x20               {set_call},\n\
                                     \x20               {get_expr},\n\
                                     \x20               |c, mut cb| c.subscribe_{event}(move |_| cb()),\n\
                                     \x20           )\n\
                                     \x20       }})\n\
                                     \x20   }}\n"
                                ));
                            }
                            TwoWaySpec::Dual {
                                get_expr,
                                event_a,
                                event_b,
                            } => {
                                out.push_str(&format!(
                                    "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<{prop_type}, M> + 'static) -> Self {{\n\
                                     \x20       let binding = value.into_prop();\n\
                                     \x20       self.with_op(move |scope, control| {{\n\
                                     \x20           crate::view::apply_two_way_prop_dual(\n\
                                     \x20               scope,\n\
                                     \x20               control,\n\
                                     \x20               binding,\n\
                                     \x20               {set_call},\n\
                                     \x20               {get_expr},\n\
                                     \x20               |c, mut cb| c.subscribe_{event_a}(move |_| cb()),\n\
                                     \x20               |c, mut cb| c.subscribe_{event_b}(move |_| cb()),\n\
                                     \x20           )\n\
                                     \x20       }})\n\
                                     \x20   }}\n"
                                ));
                            }
                        }
                    } else {
                        out.push_str(&format!(
                            "    pub fn {builder}<M>(self, value: impl crate::view::IntoProp<{prop_type}, M> + 'static) -> Self {{\n\
                             \x20       let binding = value.into_prop();\n\
                             \x20       self.with_op(move |_, control| {{\n\
                             \x20           crate::view::apply_prop(control, binding, {set_call})\n\
                             \x20       }})\n\
                             \x20   }}\n"
                        ));
                    }

                    // Also emit `is_*` alias on `El<T>` when `builder_raw != snake` (e.g. `is_checked` alongside `checked`)!
                    if builder_raw != snake && !reserved_methods.contains(&snake) {
                        let snake_ident = escape_ident(&snake);
                        out.push_str(&format!(
                            "    pub fn {snake_ident}<M>(self, value: impl crate::view::IntoProp<{prop_type}, M> + 'static) -> Self {{\n\
                             \x20       self.{builder}(value)\n\
                             \x20   }}\n"
                        ));
                    }
                }
            }
        }
        for event in &owner.events {
            let event_name = to_snake(&event.name);
            let arg_type = if event.payload_kind == "Args" {
                let args_name = simple_name(
                    event
                        .args_interface_name
                        .as_deref()
                        .expect("argsInterfaceName"),
                );
                format!("&mut {}", interface_suffix(args_name))
            } else if !event.parameters.is_empty() {
                format!("&mut {}", event_arguments_name(event))
            } else {
                "()".to_string()
            };
            out.push_str(&format!(
                "    pub fn on_{event_name}<R: crate::IntoEventResult + 'static>(self, callback: impl FnMut({arg_type}) -> R + 'static) -> Self {{\n\
                 \x20       self.with_op(move |scope, control| {{\n\
                 \x20           scope.retain_subscription(control.subscribe_{event_name}(callback)?);\n\
                 \x20           Ok(())\n\
                 \x20       }})\n\
                 \x20   }}\n"
            ));
        }
    }

    if is_control(ir, ty) {
        for property in &ir.attached_properties {
            let owner = to_snake(&property.owner_name);
            let name = to_snake(&property.name);
            let enum_name = simple_name(&property.managed_type_name);
            let is_enum = regular_enums.contains(property.managed_type_name.as_str())
                || flags_enums.contains(property.managed_type_name.as_str());
            let prop_type = if property.kind == "StringUtf16" {
                "String".to_string()
            } else if is_enum {
                enum_name.to_string()
            } else if property.kind == "TimeSpanI64" {
                "std::time::Duration".to_string()
            } else if let Some(geometry) = geometry::find(&property.kind) {
                if property.is_nullable {
                    format!("Option<{}>", geometry.safe_name)
                } else {
                    geometry.safe_name.to_string()
                }
            } else {
                rust_scalar_kind(&property.kind).to_string()
            };
            out.push_str(&format!(
                "    pub fn {owner}_{name}<M>(self, value: impl crate::view::IntoProp<{prop_type}, M> + 'static) -> Self {{\n\
                 \x20       let binding = value.into_prop();\n\
                 \x20       self.with_op(move |_, control| {{\n\
                 \x20           crate::view::apply_prop(control, binding, |c, v| c.set_{owner}_{name}(v))\n\
                 \x20       }})\n\
                 \x20   }}\n"
            ));
        }
    }

    if all_props
        .iter()
        .any(|p| p.kind == "ComCollection" && p.name == "Children")
    {
        out.push_str(
            "    pub fn rsx_child(self, value: impl crate::view::IntoChildEl + 'static) -> Self {\n\
             \x20       self.child(value)\n\
             \x20   }\n",
        );
    } else if all_props.iter().any(|p| {
        p.can_write
            && p.kind == "ComInterface"
            && p.name == "Content"
            && p.interface_name.as_deref().map(simple_name) == Some("IAvnControl")
    }) {
        out.push_str(
            "    pub fn rsx_child(self, value: impl crate::view::IntoContentEl + 'static) -> Self {\n\
             \x20       self.content(value)\n\
             \x20   }\n",
        );
    } else if all_props.iter().any(|p| {
        p.can_write
            && p.kind == "ComInterface"
            && p.name == "Child"
            && p.interface_name.as_deref().map(simple_name) == Some("IAvnControl")
    }) {
        out.push_str(
            "    pub fn rsx_child(self, value: impl crate::view::IntoContentEl + 'static) -> Self {\n\
             \x20       self.child(value)\n\
             \x20   }\n",
        );
    } else if all_props
        .iter()
        .any(|p| p.kind == "ComCollection" && p.name == "Items")
    {
        out.push_str(
            "    pub fn rsx_child(self, value: impl crate::view::IntoChildEl + 'static) -> Self {\n\
             \x20       self.item(value)\n\
             \x20   }\n",
        );
    } else if all_props
        .iter()
        .any(|p| p.can_write && p.kind == "StringUtf16" && p.name == "Text")
    {
        out.push_str(
            "    pub fn rsx_child<M>(self, value: impl crate::view::IntoProp<String, M> + 'static) -> Self {\n\
             \x20       self.text(value)\n\
             \x20   }\n",
        );
    }

    out.push_str("}\n");
    out
}

enum TwoWaySpec {
    Single {
        get_expr: String,
        event: &'static str,
    },
    Dual {
        get_expr: String,
        event_a: &'static str,
        event_b: &'static str,
    },
}

fn el_two_way_spec(
    property: &ProjectedProperty,
    getter: &str,
    has_event: impl Fn(&str) -> bool,
) -> Option<TwoWaySpec> {
    if !property.can_read {
        return None;
    }
    match (
        property.name.as_str(),
        property.kind.as_str(),
        property.string_converter_type_name.as_deref(),
    ) {
        ("Text", "StringUtf16", None) if has_event("TextChanging") || has_event("TextChanged") => {
            let event = if has_event("TextChanging") {
                "text_changing"
            } else {
                "text_changed"
            };
            let get_expr = if property.is_nullable {
                format!("|c: &_| c.{getter}().map(|v| v.unwrap_or_default())")
            } else {
                format!("|c: &_| c.{getter}()")
            };
            Some(TwoWaySpec::Single { get_expr, event })
        }
        ("IsChecked", "NullableBool", _) | ("IsChecked", "Bool", _)
            if has_event("IsCheckedChanged") =>
        {
            Some(TwoWaySpec::Single {
                get_expr: format!("|c| c.{getter}()"),
                event: "is_checked_changed",
            })
        }
        ("Value", "F64", _) if has_event("ValueChanged") => Some(TwoWaySpec::Single {
            get_expr: format!("|c| c.{getter}()"),
            event: "value_changed",
        }),
        ("Value", "StringUtf16", Some("Avalonia.Host.Com.AvnDecimal"))
            if has_event("ValueChanged") =>
        {
            Some(TwoWaySpec::Single {
                get_expr: format!("|c| c.{getter}()"),
                event: "value_changed",
            })
        }
        ("SelectedIndex", "I32", _) if has_event("SelectionChanged") => Some(TwoWaySpec::Single {
            get_expr: format!("|c| c.{getter}()"),
            event: "selection_changed",
        }),
        ("SelectedPageIndex", "I32", _) if has_event("SelectedIndexChanged") => {
            Some(TwoWaySpec::Single {
                get_expr: format!("|c| c.{getter}()"),
                event: "selected_index_changed",
            })
        }
        ("SelectedItem", "Variant", _) if has_event("SelectionChanged") => {
            Some(TwoWaySpec::Single {
                get_expr: format!("|c| c.{getter}()"),
                event: "selection_changed",
            })
        }
        (
            "SelectedDate",
            "StringUtf16",
            Some("Avalonia.Host.Com.AvnCalendarDate" | "Avalonia.Host.Com.AvnDateTimeOffset"),
        ) if has_event("SelectedDateChanged") => Some(TwoWaySpec::Single {
            get_expr: format!("|c| c.{getter}()"),
            event: "selected_date_changed",
        }),
        ("SelectedTime", "StringUtf16", Some("Avalonia.Host.Com.AvnTimeSpan"))
            if has_event("SelectedTimeChanged") =>
        {
            Some(TwoWaySpec::Single {
                get_expr: format!("|c| c.{getter}()"),
                event: "selected_time_changed",
            })
        }
        ("IsExpanded", "Bool", _) if has_event("Expanded") && has_event("Collapsed") => {
            Some(TwoWaySpec::Dual {
                get_expr: format!("|c: &_| c.{getter}()"),
                event_a: "expanded",
                event_b: "collapsed",
            })
        }
        ("IsPaneOpen", "Bool", _) if has_event("PaneOpened") && has_event("PaneClosed") => {
            Some(TwoWaySpec::Dual {
                get_expr: format!("|c: &_| c.{getter}()"),
                event_a: "pane_opened",
                event_b: "pane_closed",
            })
        }
        ("IsOpen", "Bool", _) if has_event("Opened") && has_event("Closed") => {
            Some(TwoWaySpec::Dual {
                get_expr: format!("|c: &_| c.{getter}()"),
                event_a: "opened",
                event_b: "closed",
            })
        }
        ("IsDropDownOpen", "Bool", _)
            if has_event("DropDownOpened") && has_event("DropDownClosed") =>
        {
            Some(TwoWaySpec::Dual {
                get_expr: format!("|c: &_| c.{getter}()"),
                event_a: "drop_down_opened",
                event_b: "drop_down_closed",
            })
        }
        _ => None,
    }
}

fn el_prop_type(
    property: &ProjectedProperty,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    if let Some((ty, _, _)) = string_converter_mapping(property) {
        return ty.to_string();
    }
    if property.kind == "StringUtf16" {
        "String".to_string()
    } else if property.kind == "Brush" {
        "Option<Paint>".to_string()
    } else if property.kind == "Variant" {
        "Variant".to_string()
    } else if property.kind == "TimeSpanI64" {
        "std::time::Duration".to_string()
    } else if property.kind == "PixelPointI32" {
        "PixelPoint".to_string()
    } else {
        safe_scalar_type(property, flags_enums, regular_enums)
    }
}

fn el_setter_expr(_property: &ProjectedProperty, builder_raw: &str) -> String {
    format!("|c, v| c.set_{builder_raw}(v)")
}

fn safe_callback_type(kind: &str) -> &'static str {
    match kind {
        "ItemFilter" => "crate::ItemFilter",
        "TextFilter" => "crate::TextFilter",
        "ItemSelector" => "crate::ItemSelector",
        "TextSelector" => "crate::TextSelector",
        "PopupPlacement" => "crate::PopupPlacementCallback",
        "AsyncPopulator" => "crate::AsyncPopulator",
        _ => unreachable!(),
    }
}

fn string_converter_mapping(
    property: &ProjectedProperty,
) -> Option<(&'static str, &'static str, &'static str)> {
    match property.string_converter_type_name.as_deref()? {
        "Avalonia.Host.Com.AvnColumnDefinitions" | "Avalonia.Host.Com.AvnRowDefinitions" => Some((
            "crate::GridTracks",
            "impl crate::view::IntoValue<crate::GridTracks>",
            "grid_tracks",
        )),
        "Avalonia.Host.Com.AvnCalendarDate" | "Avalonia.Host.Com.AvnDateTimeOffset" => Some((
            "Option<crate::CivilDate>",
            "impl Into<Option<crate::CivilDate>>",
            "opt_civil_date",
        )),
        "Avalonia.Host.Com.AvnCalendarDateValue" | "Avalonia.Host.Com.AvnDateTimeOffsetValue" => {
            Some(("crate::CivilDate", "crate::CivilDate", "civil_date"))
        }
        "Avalonia.Host.Com.AvnTimeSpan" => Some((
            "Option<crate::CivilTime>",
            "impl Into<Option<crate::CivilTime>>",
            "opt_civil_time",
        )),
        "Avalonia.Host.Com.AvnDecimal" => Some((
            "Option<crate::Decimal>",
            "impl crate::view::IntoValue<Option<crate::Decimal>>",
            "opt_decimal",
        )),
        "Avalonia.Host.Com.AvnDecimalValue" => Some((
            "crate::Decimal",
            "impl crate::view::IntoValue<crate::Decimal>",
            "decimal",
        )),
        _ => None,
    }
}

fn getter_name(snake: &str, reserved_methods: &std::collections::HashSet<String>) -> String {
    if reserved_methods.contains(snake) {
        format!("get_{snake}")
    } else {
        escape_ident(snake)
    }
}

fn escape_ident(name: &str) -> String {
    match name {
        "as" | "break" | "const" | "continue" | "crate" | "else" | "enum" | "extern" | "false"
        | "fn" | "for" | "if" | "impl" | "in" | "let" | "loop" | "match" | "mod" | "move"
        | "mut" | "pub" | "ref" | "return" | "self" | "Self" | "static" | "struct" | "super"
        | "trait" | "true" | "type" | "unsafe" | "use" | "where" | "while" | "async" | "await"
        | "dyn" | "box" | "try" => format!("r#{name}"),
        _ => name.to_string(),
    }
}

fn emit_property(
    property: &ProjectedProperty,
    reserved_methods: &std::collections::HashSet<String>,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    let snake = to_snake(&property.name);
    let getter = getter_name(&snake, reserved_methods);
    let builder_raw = if property.kind == "Bool" || property.kind == "NullableBool" {
        match snake.strip_prefix("is_") {
            Some(stripped) if !reserved_methods.contains(stripped) => stripped,
            _ => snake.as_str(),
        }
    } else {
        snake.as_str()
    };
    let mut out = String::new();

    if property.can_read {
        if let Some((ty, _, conv_tag)) = string_converter_mapping(property) {
            let body = match conv_tag {
                "grid_tracks" => format!(
                    "        let raw = unsafe {{ sys::take_utf16(self.raw.get_{snake}()?).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER)))? }};\n\
                     \x20       raw.parse()"
                ),
                "opt_civil_date" => format!(
                    "        let raw = unsafe {{ sys::take_utf16(self.raw.get_{snake}()?) }};\n\
                     \x20       raw.as_deref().filter(|s| !s.is_empty()).map(crate::CivilDate::from_abi_str).transpose()"
                ),
                "civil_date" => format!(
                    "        let raw = unsafe {{ sys::take_utf16(self.raw.get_{snake}()?).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER)))? }};\n\
                     \x20       crate::CivilDate::from_abi_str(&raw)"
                ),
                "opt_civil_time" => format!(
                    "        let raw = unsafe {{ sys::take_utf16(self.raw.get_{snake}()?) }};\n\
                     \x20       raw.as_deref().filter(|s| !s.is_empty()).map(crate::CivilTime::from_abi_str).transpose()"
                ),
                "opt_decimal" => format!(
                    "        let raw = unsafe {{ sys::take_utf16(self.raw.get_{snake}()?) }};\n\
                     \x20       raw.as_deref().filter(|s| !s.is_empty()).map(crate::Decimal::from_abi_str).transpose()"
                ),
                "decimal" => format!(
                    "        let raw = unsafe {{ sys::take_utf16(self.raw.get_{snake}()?).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER)))? }};\n\
                     \x20       crate::Decimal::from_abi_str(&raw)"
                ),
                _ => unreachable!(),
            };
            out.push_str(&format!(
                "    pub fn {getter}(&self) -> Result<{ty}> {{\n{body}\n    }}\n"
            ));
        } else {
            match property.kind.as_str() {
                "StringUtf16" if property.is_nullable => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<Option<String>> {{\n\
                     \x20       unsafe {{ Ok(sys::take_utf16(self.raw.get_{snake}()?)) }}\n\
                     \x20   }}\n"
                )),
                "StringUtf16" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<String> {{\n\
                     \x20       unsafe {{ sys::take_utf16(self.raw.get_{snake}()?).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER))) }}\n\
                     \x20   }}\n"
                )),
                "ComInterface" => {
                    let safe_type = interface_suffix(simple_name(
                        property.interface_name.as_deref().expect("interfaceName"),
                    ));
                    if property.is_nullable {
                        out.push_str(&format!(
                            "    pub fn {getter}(&self) -> Result<Option<{safe_type}>> {{\n\
                             \x20       Ok(self.raw.get_{snake}()?.map(|raw| {safe_type} {{ raw }}))\n\
                             \x20   }}\n"
                        ));
                    } else {
                        out.push_str(&format!(
                            "    pub fn {getter}(&self) -> Result<{safe_type}> {{\n\
                             \x20       Ok({safe_type} {{ raw: self.raw.get_{snake}()? }})\n\
                             \x20   }}\n"
                        ));
                    }
                }
                "ComCollection" => {
                    let safe_type = interface_suffix(simple_name(
                        property.interface_name.as_deref().expect("interfaceName"),
                    ));
                    if property.is_nullable {
                        out.push_str(&format!(
                            "    pub fn {getter}(&self) -> Result<Option<{safe_type}>> {{\n\
                             \x20       Ok(self.raw.get_{snake}()?.map(|raw| {safe_type} {{ raw }}))\n\
                             \x20   }}\n"
                        ));
                    } else {
                        out.push_str(&format!(
                            "    pub fn {getter}(&self) -> Result<{safe_type}> {{\n\
                             \x20       Ok({safe_type} {{ raw: self.raw.get_{snake}()? }})\n\
                             \x20   }}\n"
                        ));
                    }
                }
                "Brush" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<Option<Paint>> {{\n\
                     \x20       self.raw.get_{snake}()?.as_ref().map(Paint::from_raw).transpose()\n\
                     \x20   }}\n"
                )),
                "Command" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<Option<crate::Command>> {{\n\
                     \x20       Ok(self.raw.get_{snake}()?.map(crate::Command::from_com_ptr))\n\
                     \x20   }}\n"
                )),
                "DataTemplate" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<Option<DataTemplate>> {{\n\
                     \x20       Ok(self.raw.get_{snake}()?.map(|raw| DataTemplate {{ raw }}))\n\
                     \x20   }}\n"
                )),
                "ItemFilter" | "TextFilter" | "ItemSelector" | "TextSelector"
                | "PopupPlacement" | "AsyncPopulator" => {
                    let cb_type = safe_callback_type(&property.kind);
                    out.push_str(&format!(
                        "    pub fn {getter}(&self) -> Result<Option<{cb_type}>> {{\n\
                         \x20       Ok(self.raw.get_{snake}()?.map(|raw| {cb_type} {{ raw }}))\n\
                         \x20   }}\n"
                    ));
                }
                "Variant" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<Variant> {{\n\
                     \x20       Ok(Variant::from_abi(self.raw.get_{snake}()?))\n\
                     \x20   }}\n"
                )),
                "TimeSpanI64" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<std::time::Duration> {{\n\
                     \x20       let ticks = self.raw.get_{snake}()?;\n\
                     \x20       Ok(std::time::Duration::from_nanos(ticks.clamp(0, i64::MAX / 100) as u64 * 100))\n\
                     \x20   }}\n"
                )),
                "PixelPointI32" => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<PixelPoint> {{\n\
                     \x20       Ok(PixelPoint::from_abi(self.raw.get_{snake}()?))\n\
                     \x20   }}\n"
                )),
                "I32"
                    if property
                        .managed_type_name
                        .as_deref()
                        .is_some_and(|m| flags_enums.contains(m)) =>
                {
                    let enum_name = simple_name(property.managed_type_name.as_deref().unwrap());
                    out.push_str(&format!(
                        "    pub fn {getter}(&self) -> Result<{enum_name}> {{\n\
                         \x20       Ok({enum_name}::from_bits_retain(self.raw.get_{snake}()?))\n\
                         \x20   }}\n"
                    ));
                }
                "I32"
                    if property
                        .managed_type_name
                        .as_deref()
                        .is_some_and(|m| regular_enums.contains(m)) =>
                {
                    let enum_name = simple_name(property.managed_type_name.as_deref().unwrap());
                    out.push_str(&format!(
                        "    pub fn {getter}(&self) -> Result<{enum_name}> {{\n\
                         \x20       let value = self.raw.get_{snake}()?;\n\
                         \x20       {enum_name}::try_from(value)\n\
                         \x20   }}\n"
                    ));
                }
                kind if geometry::is_geometry(kind) => {
                    let safe_type = geometry::find(kind).unwrap().safe_name;
                    if property.is_nullable {
                        out.push_str(&format!(
                            "    pub fn {getter}(&self) -> Result<Option<{safe_type}>> {{\n\
                             \x20       Ok({safe_type}::from_optional_abi(self.raw.get_{snake}()?))\n\
                             \x20   }}\n"
                        ));
                    } else {
                        out.push_str(&format!(
                            "    pub fn {getter}(&self) -> Result<{safe_type}> {{\n\
                             \x20       Ok(self.raw.get_{snake}()?.into())\n\
                             \x20   }}\n"
                        ));
                    }
                }
                _ => out.push_str(&format!(
                    "    pub fn {getter}(&self) -> Result<{}> {{ Ok(self.raw.get_{snake}()?) }}\n",
                    safe_scalar_type(property, flags_enums, regular_enums)
                )),
            }
        }
    }

    if property.can_write {
        let (argument, setup, value) = safe_property_input(property, flags_enums, regular_enums);
        out.push_str(&format!(
            "    pub fn set_{builder_raw}(&self, value: {argument}) -> Result<()> {{\n{setup}        Ok(self.raw.set_{snake}({value})?)\n    }}\n"
        ));
    }
    out
}

fn emit_event(event: &ProjectedEvent) -> String {
    if event.payload_kind == "Args" {
        let event_name = to_snake(&event.name);
        let raw_args_name = simple_name(
            event
                .args_interface_name
                .as_deref()
                .expect("argsInterfaceName"),
        );
        let safe_args = interface_suffix(raw_args_name);
        let handler_name = simple_name(&event.handler_interface_name)
            .strip_prefix("IAvn")
            .unwrap_or_else(|| simple_name(&event.handler_interface_name))
            .strip_suffix("Handler")
            .unwrap_or_else(|| simple_name(&event.handler_interface_name));
        let handler_function = format!("{}_handler", to_snake(handler_name));
        return format!(
            "    pub fn subscribe_{event_name}<R: crate::IntoEventResult>(&self, mut callback: impl FnMut(&mut {safe_args}) -> R + 'static) -> Result<EventSubscription> {{\n\
             \x20       let cb = crate::reactive::UiCallbackHandle::new(move |args: &mut {safe_args}| {{\n\
             \x20           if let Err(err) = callback(args).into_event_result() {{\n\
             \x20               crate::runtime::report_ui_error(\"{event_name} callback failed\", &err);\n\
             \x20           }}\n\
             \x20       }});\n\
             \x20       let handler = sys::{handler_function}(move |raw_args| {{\n\
             \x20           let mut safe = {safe_args}::from_raw(raw_args)?;\n\
             \x20           let _ = cb.with(|f| f(&mut safe));\n\
             \x20           Ok(())\n\
             \x20       }});\n\
             \x20       let subscription_id = self.raw.advise_{event_name}(&handler)?;\n\
             \x20       let source = self.raw.clone();\n\
             \x20       Ok(EventSubscription::new(move || source.unadvise_{event_name}(subscription_id)))\n\
             \x20   }}\n\
             \x20   pub fn on_{event_name}<R: crate::IntoEventResult>(&self, scope: &crate::AppScope, callback: impl FnMut(&mut {safe_args}) -> R + 'static) -> Result<()> {{\n\
             \x20       scope.retain_subscription(self.subscribe_{event_name}(callback)?);\n\
             \x20       Ok(())\n\
             \x20   }}\n"
        );
    }
    if !event.parameters.is_empty() {
        let event_name = to_snake(&event.name);
        let args_name = event_arguments_name(event);
        let handler_name = simple_name(&event.handler_interface_name)
            .strip_prefix("IAvn")
            .unwrap_or_else(|| simple_name(&event.handler_interface_name))
            .strip_suffix("Handler")
            .unwrap_or_else(|| simple_name(&event.handler_interface_name));
        let handler_function = format!("{}_handler", to_snake(handler_name));
        return format!(
            "    pub fn subscribe_{event_name}<R: crate::IntoEventResult>(&self, mut callback: impl FnMut(&mut {args_name}) -> R + 'static) -> Result<EventSubscription> {{\n\
             \x20       let cb = crate::reactive::UiCallbackHandle::new(move |ev: &mut {args_name}| {{\n\
             \x20           if let Err(err) = callback(ev).into_event_result() {{\n\
             \x20               crate::runtime::report_ui_error(\"{event_name} callback failed\", &err);\n\
             \x20           }}\n\
             \x20       }});\n\
             \x20       let handler = sys::{handler_function}(move |raw_event| {{\n\
             \x20           let mut safe = {args_name}::from_sys(raw_event)?;\n\
             \x20           let _ = cb.with(|f| f(&mut safe));\n\
             \x20           safe.write_back(raw_event);\n\
             \x20           Ok(())\n\
             \x20       }});\n\
             \x20       let subscription_id = self.raw.advise_{event_name}(&handler)?;\n\
             \x20       let source = self.raw.clone();\n\
             \x20       Ok(EventSubscription::new(move || source.unadvise_{event_name}(subscription_id)))\n\
             \x20   }}\n\
             \x20   pub fn on_{event_name}<R: crate::IntoEventResult>(&self, scope: &crate::AppScope, callback: impl FnMut(&mut {args_name}) -> R + 'static) -> Result<()> {{\n\
             \x20       scope.retain_subscription(self.subscribe_{event_name}(callback)?);\n\
             \x20       Ok(())\n\
             \x20   }}\n"
        );
    }
    assert_eq!(event.payload_kind, "None", "unsupported event payload kind");
    let event_name = to_snake(&event.name);
    let handler_name = simple_name(&event.handler_interface_name)
        .strip_prefix("IAvn")
        .unwrap_or_else(|| simple_name(&event.handler_interface_name))
        .strip_suffix("Handler")
        .unwrap_or_else(|| {
            simple_name(&event.handler_interface_name)
                .strip_prefix("IAvn")
                .unwrap_or_else(|| simple_name(&event.handler_interface_name))
        });
    let handler_function = format!("{}_handler", to_snake(handler_name));
    format!(
        "    pub fn subscribe_{event_name}<R: crate::IntoEventResult>(&self, mut callback: impl FnMut(()) -> R + 'static) -> Result<EventSubscription> {{\n\
         \x20       let cb = crate::reactive::UiCallbackHandle::new(move || {{\n\
         \x20           if let Err(err) = callback(()).into_event_result() {{\n\
         \x20               crate::runtime::report_ui_error(\"{event_name} callback failed\", &err);\n\
         \x20           }}\n\
         \x20       }});\n\
         \x20       let handler = sys::{handler_function}(move || {{\n\
         \x20           let _ = cb.with(|f| f());\n\
         \x20           Ok(())\n\
         \x20       }});\n\
         \x20       let subscription_id = self.raw.advise_{event_name}(&handler)?;\n\
         \x20       let source = self.raw.clone();\n\
         \x20       Ok(EventSubscription::new(move || source.unadvise_{event_name}(subscription_id)))\n\
         \x20   }}\n\
         \x20   pub fn on_{event_name}<R: crate::IntoEventResult>(&self, scope: &crate::AppScope, callback: impl FnMut(()) -> R + 'static) -> Result<()> {{\n\
         \x20       scope.retain_subscription(self.subscribe_{event_name}(callback)?);\n\
         \x20       Ok(())\n\
         \x20   }}\n"
    )
}

fn event_arguments_name(event: &ProjectedEvent) -> String {
    let handler = simple_name(&event.handler_interface_name);
    format!(
        "{}EventArgs",
        handler
            .strip_prefix("IAvn")
            .unwrap_or(handler)
            .strip_suffix("Handler")
            .unwrap_or(handler)
    )
}

fn emit_method(
    ty: &ProjectedType,
    method: &crate::ir::ProjectedMethod,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    let name = to_snake(&method.name);
    if ty.name == "IAvnWindow" && method.name == "Show" {
        return String::new();
    }
    let is_any_control = |parameter: &crate::ir::ProjectedParameter| {
        parameter.kind == "ComInterface"
            && parameter
                .interface_name
                .as_deref()
                .map(simple_name)
                .map(interface_suffix)
                == Some("Control")
    };
    let ins: Vec<_> = method
        .parameters
        .iter()
        .filter(|parameter| parameter.direction != "Out")
        .collect();
    let outs: Vec<_> = method
        .parameters
        .iter()
        .filter(|parameter| parameter.direction == "Out")
        .collect();
    let arguments = ins
        .iter()
        .map(|parameter| {
            let parameter_name = to_snake(&parameter.name);
            if is_any_control(parameter) {
                if parameter.is_nullable {
                    format!("{parameter_name}: Option<&impl AsControl>")
                } else {
                    format!("{parameter_name}: &impl AsControl")
                }
            } else if parameter.kind == "ComInterface" {
                let safe = interface_suffix(simple_name(
                    parameter.interface_name.as_deref().expect("interfaceName"),
                ));
                if parameter.is_nullable {
                    format!("{parameter_name}: Option<&{safe}>")
                } else {
                    format!("{parameter_name}: &{safe}")
                }
            } else if parameter.kind == "Notification" {
                if parameter.is_nullable {
                    format!("{parameter_name}: Option<&crate::Notification>")
                } else {
                    format!("{parameter_name}: &crate::Notification")
                }
            } else if parameter.kind == "Variant" {
                format!("{parameter_name}: impl Into<Variant>")
            } else if parameter.kind == "StringUtf16" {
                if parameter.is_nullable {
                    format!("{parameter_name}: Option<&str>")
                } else {
                    format!("{parameter_name}: impl AsRef<str>")
                }
            } else if parameter.kind == "I32"
                && parameter
                    .managed_type_name
                    .as_deref()
                    .is_some_and(|m| flags_enums.contains(m) || regular_enums.contains(m))
            {
                let enum_name = simple_name(parameter.managed_type_name.as_deref().unwrap());
                format!("{parameter_name}: {enum_name}")
            } else if let Some(geometry) = geometry::find(&parameter.kind) {
                format!("{parameter_name}: {}", geometry.safe_name)
            } else {
                format!("{parameter_name}: {}", rust_scalar_kind(&parameter.kind))
            }
        })
        .collect::<Vec<_>>()
        .join(", ");
    let setup = ins
        .iter()
        .filter(|parameter| {
            is_any_control(parameter)
                || parameter.kind == "StringUtf16"
                || parameter.kind == "Notification"
        })
        .map(|parameter| {
            let parameter_name = to_snake(&parameter.name);
            if parameter.kind == "StringUtf16" {
                if parameter.is_nullable {
                    format!("        let {parameter_name}: Option<Vec<u16>> = {parameter_name}.map(|value| value.encode_utf16().chain(Some(0)).collect());\n")
                } else {
                    format!("        let {parameter_name}: Vec<u16> = {parameter_name}.as_ref().encode_utf16().chain(Some(0)).collect();\n")
                }
            } else if parameter.kind == "Notification" {
                if parameter.is_nullable {
                    format!("        let {parameter_name} = {parameter_name}.map(crate::Notification::to_raw);\n")
                } else {
                    format!("        let {parameter_name} = {parameter_name}.to_raw();\n")
                }
            } else if parameter.is_nullable {
                format!(
                    "        let {parameter_name} = {parameter_name}.map(|value| value.as_control()).transpose()?;\n"
                )
            } else {
                format!("        let {parameter_name} = {parameter_name}.as_control()?;\n")
            }
        })
        .collect::<String>();
    let call_arguments = ins
        .iter()
        .map(|parameter| {
            let parameter_name = to_snake(&parameter.name);
            if is_any_control(parameter) {
                if parameter.is_nullable {
                    format!("{parameter_name}.as_ref()")
                } else {
                    format!("&{parameter_name}")
                }
            } else if parameter.kind == "ComInterface" {
                if parameter.is_nullable {
                    format!("{parameter_name}.map(|value| &value.raw)")
                } else {
                    format!("&{parameter_name}.raw")
                }
            } else if parameter.kind == "Notification" {
                if parameter.is_nullable {
                    format!("{parameter_name}.as_ref()")
                } else {
                    format!("&{parameter_name}")
                }
            } else if parameter.kind == "StringUtf16" {
                if parameter.is_nullable {
                    format!("{parameter_name}.as_deref()")
                } else {
                    format!("&{parameter_name}")
                }
            } else if parameter.kind == "Variant" {
                format!("*{parameter_name}.into().to_abi()?")
            } else if parameter.kind == "I32"
                && parameter
                    .managed_type_name
                    .as_deref()
                    .is_some_and(|m| flags_enums.contains(m))
            {
                format!("{parameter_name}.bits()")
            } else if parameter.kind == "I32"
                && parameter
                    .managed_type_name
                    .as_deref()
                    .is_some_and(|m| regular_enums.contains(m))
            {
                format!("{parameter_name} as i32")
            } else if geometry::is_geometry(&parameter.kind) {
                format!("{parameter_name}.into()")
            } else {
                parameter_name
            }
        })
        .collect::<Vec<_>>()
        .join(", ");
    let separator = if arguments.is_empty() { "" } else { ", " };
    let (result_type, result_expr): (String, String) = match outs.as_slice() {
        [] => (
            "()".into(),
            format!("Ok(self.raw.{name}({call_arguments})?)"),
        ),
        [output] if output.kind == "Bool" => (
            "bool".into(),
            format!("Ok(self.raw.{name}({call_arguments})? != 0)"),
        ),
        [output] if output.kind == "StringUtf16" => (
            "String".into(),
            format!("unsafe {{ sys::take_utf16(self.raw.{name}({call_arguments})?).ok_or(crate::Error::Abi(sys::Error(sys::E_POINTER))) }}"),
        ),
        [output] if output.kind == "Variant" => (
            "Variant".into(),
            format!("Ok(Variant::from_abi(self.raw.{name}({call_arguments})?))"),
        ),
        [output] if output.kind == "ComInterface" => {
            let safe = interface_suffix(simple_name(
                output.interface_name.as_deref().expect("interfaceName"),
            ));
            if output.is_nullable {
                (
                    format!("Option<{safe}>"),
                    format!(
                        "Ok(self.raw.{name}({call_arguments})?.map(|raw| {safe} {{ raw }}))"
                    ),
                )
            } else {
                (
                    safe.to_string(),
                    format!("Ok({safe} {{ raw: self.raw.{name}({call_arguments})? }})"),
                )
            }
        }
        [output] => (
            rust_scalar_kind(&output.kind).into(),
            format!("Ok(self.raw.{name}({call_arguments})?)"),
        ),
        _ => ("()".into(), format!("Ok(self.raw.{name}({call_arguments})?)")),
    };
    if setup.is_empty() && !result_expr.contains('\n') {
        return format!(
            "    pub fn {name}(&self{separator}{arguments}) -> Result<{result_type}> {{ {result_expr} }}\n"
        );
    }
    format!(
        "    pub fn {name}(&self{separator}{arguments}) -> Result<{result_type}> {{\n\
         {setup}        {result_expr}\n\
         \x20   }}\n"
    )
}

fn safe_property_input(
    property: &ProjectedProperty,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> (String, String, String) {
    if let Some((_, input_ty, conv_tag)) = string_converter_mapping(property) {
        return match conv_tag {
            "grid_tracks" => (
                input_ty.into(),
                "        let value: Vec<u16> = value.into_value().to_string().encode_utf16().chain(Some(0)).collect();\n".into(),
                "&value".into(),
            ),
            "opt_civil_date" => (
                input_ty.into(),
                "        let value: Option<Vec<u16>> = value.into().map(|d: crate::CivilDate| d.to_abi_string().encode_utf16().chain(Some(0)).collect());\n".into(),
                "value.as_deref()".into(),
            ),
            "civil_date" => (
                input_ty.into(),
                "        let value: Vec<u16> = value.to_abi_string().encode_utf16().chain(Some(0)).collect();\n".into(),
                "&value".into(),
            ),
            "opt_civil_time" => (
                input_ty.into(),
                "        let value: Option<Vec<u16>> = value.into().map(|t: crate::CivilTime| t.to_abi_string().encode_utf16().chain(Some(0)).collect());\n".into(),
                "value.as_deref()".into(),
            ),
            "opt_decimal" => (
                input_ty.into(),
                "        let value: Option<Vec<u16>> = value.into_value().map(|d: crate::Decimal| d.to_abi_string().encode_utf16().chain(Some(0)).collect());\n".into(),
                "value.as_deref()".into(),
            ),
            "decimal" => (
                input_ty.into(),
                "        let value: Vec<u16> = value.into_value().to_abi_string().encode_utf16().chain(Some(0)).collect();\n".into(),
                "&value".into(),
            ),
            _ => unreachable!(),
        };
    }
    if let Some(geometry) = geometry::find(&property.kind) {
        if property.is_nullable {
            return (
                format!("impl Into<Option<{}>>", geometry.safe_name),
                String::new(),
                format!("{}::to_optional_abi(value.into())", geometry.safe_name),
            );
        }
        return (
            format!("impl Into<{}>", geometry.safe_name),
            String::new(),
            "value.into().into()".into(),
        );
    }
    match property.kind.as_str() {
        "StringUtf16" => (
            "impl AsRef<str>".into(),
            "        let value: Vec<u16> = value.as_ref().encode_utf16().chain(Some(0)).collect();\n"
                .into(),
            if property.is_nullable {
                "Some(&value)".into()
            } else {
                "&value".into()
            },
        ),
        "ComInterface" => {
            let safe = interface_suffix(simple_name(
                property.interface_name.as_deref().expect("interfaceName"),
            ));
            if safe == "Control" {
                if property.is_nullable {
                    return (
                        "impl crate::IntoContent".into(),
                        "        let value = value.into_content_control()?;\n".into(),
                        "value.as_ref()".into(),
                    );
                }
                (
                    "impl AsControl".into(),
                    "        let value = value.as_control()?;\n".into(),
                    "&value".into(),
                )
            } else {
                if property.is_nullable {
                    return (
                        format!("Option<&{safe}>"),
                        String::new(),
                        "value.map(|value| &value.raw)".into(),
                    );
                }
                (
                    format!("&{safe}"),
                    String::new(),
                    "&value.raw".into(),
                )
            }
        }
        "ComCollection" => {
            let safe = interface_suffix(simple_name(
                property.interface_name.as_deref().expect("interfaceName"),
            ));
            if property.is_nullable {
                (
                    format!("Option<&{safe}>"),
                    String::new(),
                    "value.map(|value| &value.raw)".into(),
                )
            } else {
                (
                    format!("&{safe}"),
                    String::new(),
                    "&value.raw".into(),
                )
            }
        }
        "Brush" => (
            "impl crate::view::IntoValue<Option<Paint>>".into(),
            "        let value = value.into_value().as_ref().map(Paint::to_raw).transpose()?;\n".into(),
            "value.as_ref()".into(),
        ),
        "Command" => (
            "impl crate::view::IntoCommandProp".into(),
            "        let value = value.into_command_prop();\n".into(),
            "value.as_ref()".into(),
        ),
        "DataTemplate" => (
            "Option<&DataTemplate>".into(),
            String::new(),
            "value.map(|value| &value.raw)".into(),
        ),
        "ItemFilter" | "TextFilter" | "ItemSelector" | "TextSelector" | "PopupPlacement"
        | "AsyncPopulator" => {
            let cb_type = safe_callback_type(&property.kind);
            (
                format!("Option<&{cb_type}>"),
                String::new(),
                "value.map(|v| &v.raw)".into(),
            )
        }
        "Variant" => (
            "impl Into<Variant>".into(),
            "        let value = value.into().to_abi()?;\n".into(),
            "&value".into(),
        ),
        "TimeSpanI64" => (
            "std::time::Duration".into(),
            "        let value = (value.as_nanos() / 100).clamp(0, i64::MAX as u128) as i64;\n".into(),
            "value".into(),
        ),
        "PixelPointI32" => (
            "impl Into<PixelPoint>".into(),
            "        let value = value.into().to_abi();\n".into(),
            "value".into(),
        ),
        "I32"
            if property
                .managed_type_name
                .as_deref()
                .is_some_and(|m| flags_enums.contains(m)) =>
        (
            simple_name(property.managed_type_name.as_deref().unwrap()).into(),
            String::new(),
            "value.bits()".into(),
        ),
        "I32"
            if property
                .managed_type_name
                .as_deref()
                .is_some_and(|m| regular_enums.contains(m)) =>
        (
            simple_name(property.managed_type_name.as_deref().unwrap()).into(),
            String::new(),
            "value as i32".into(),
        ),
        _ => (
            safe_scalar_type(property, flags_enums, regular_enums),
            String::new(),
            "value".into(),
        ),
    }
}

pub(crate) fn supports_two_way_property(
    property: &ProjectedProperty,
    has_event: impl Fn(&str) -> bool,
) -> bool {
    property.can_read
        && match (property.name.as_str(), property.kind.as_str()) {
            ("Text", "StringUtf16") => has_event("TextChanging") || has_event("TextChanged"),
            ("IsChecked", "NullableBool") => has_event("IsCheckedChanged"),
            ("Value", "F64") => has_event("ValueChanged"),
            ("SelectedIndex", "I32") => has_event("SelectionChanged"),
            _ => false,
        }
}

fn safe_scalar_type(
    property: &ProjectedProperty,
    flags_enums: &std::collections::HashSet<&str>,
    regular_enums: &std::collections::HashSet<&str>,
) -> String {
    if let Some(geometry) = geometry::find(&property.kind) {
        if property.is_nullable {
            format!("Option<{}>", geometry.safe_name)
        } else {
            geometry.safe_name.into()
        }
    } else if property.kind == "I32"
        && property
            .managed_type_name
            .as_deref()
            .is_some_and(|m| flags_enums.contains(m) || regular_enums.contains(m))
    {
        simple_name(property.managed_type_name.as_deref().unwrap()).into()
    } else {
        rust_scalar_kind(&property.kind).into()
    }
}

fn rust_scalar_kind(kind: &str) -> &str {
    match kind {
        "CharUtf16" => "u16",
        "I32" => "i32",
        "I64" => "i64",
        "TimeSpanI64" => "i64",
        "F32" => "f32",
        "F64" => "f64",
        "Bool" => "bool",
        "NullableBool" => "Option<bool>",
        _ => "()",
    }
}

fn is_control(ir: &ProjectionIr, ty: &ProjectedType) -> bool {
    lineage(ir, ty)
        .iter()
        .any(|candidate| candidate.name == "IAvnControl")
}

fn lineage<'a>(ir: &'a ProjectionIr, ty: &'a ProjectedType) -> Vec<&'a ProjectedType> {
    let mut result = vec![ty];
    let mut current = ty;
    while let Some(base) = &current.base_full_name {
        current = ir
            .types
            .iter()
            .find(|candidate| &candidate.full_name == base)
            .expect("base type must be present in projection IR");
        result.push(current);
    }
    result.reverse();
    result
}

fn unique_collections(ir: &ProjectionIr) -> Vec<&ProjectedProperty> {
    let mut result = Vec::new();
    for property in ir
        .types
        .iter()
        .flat_map(|ty| ty.properties.iter())
        .filter(|property| property.kind == "ComCollection")
    {
        if !result
            .iter()
            .any(|existing: &&ProjectedProperty| existing.interface_name == property.interface_name)
        {
            result.push(property);
        }
    }
    result
}

fn interface_suffix(name: &str) -> &str {
    name.strip_prefix("IAvn").unwrap_or(name)
}

fn simple_name(full_name: &str) -> &str {
    full_name.rsplit('.').next().unwrap_or(full_name)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{fs, path::PathBuf, process::Command, time::SystemTime};

    #[test]
    fn two_way_text_prefers_synchronous_event_when_projected() {
        let ir: ProjectionIr =
            serde_json::from_str(include_str!("../../projection.ir.json")).unwrap();
        let generated = emit_safe_module(&ir);
        let builder = |name: &str| {
            generated
                .split(&format!("impl crate::view::El<{name}> {{"))
                .nth(1)
                .unwrap()
                .split("\nimpl ")
                .next()
                .unwrap()
        };
        assert!(builder("TextBox").contains("c.subscribe_text_changing(move |_| cb())"));
        assert!(builder("AutoCompleteBox").contains("c.subscribe_text_changed(move |_| cb())"));
    }

    #[test]
    fn attached_accessors_do_not_collide_with_instance_properties() {
        let ir: ProjectionIr =
            serde_json::from_str(include_str!("../../projection.ir.json")).unwrap();
        let generated = emit_safe_module(&ir);
        assert!(generated
            .contains("pub fn attached_horizontal_scroll_bar_visibility(target: &impl AsControl)"));
        assert!(generated
            .contains("ScrollViewer::set_attached_horizontal_scroll_bar_visibility(self, value)"));
        assert!(generated.contains("pub fn column(target: &impl AsControl)"));
    }

    #[test]
    fn safe_string_methods_and_interface_setters_compile_and_preserve_nulls() {
        let ty: ProjectedType = serde_json::from_value(serde_json::json!({
            "name": "IAvnFixture", "fullName": "Tests.IAvnFixture", "kind": "Class",
            "methods": [{
                "name": "WriteStrings", "returnKind": "I32", "preserveSig": true,
                "parameters": [
                    { "name": "required", "kind": "StringUtf16", "direction": "In" },
                    { "name": "optional", "kind": "StringUtf16", "direction": "In", "isNullable": true }
                ]
            }]
        }))
        .unwrap();
        let mut members = emit_method(
            &ty,
            &ty.methods[0],
            &Default::default(),
            &Default::default(),
        );
        for (name, interface, nullable) in [
            ("RequiredControl", "IAvnControl", false),
            ("OptionalControl", "IAvnControl", true),
            ("RequiredSpecific", "IAvnSpecific", false),
            ("OptionalSpecific", "IAvnSpecific", true),
        ] {
            let property: ProjectedProperty = serde_json::from_value(serde_json::json!({
                "name": name, "kind": "ComInterface", "interfaceName": interface,
                "canWrite": true, "isNullable": nullable
            }))
            .unwrap();
            members.push_str(&emit_property(
                &property,
                &Default::default(),
                &Default::default(),
                &Default::default(),
            ));
        }
        let source = include_str!("../test-fixtures/safe_inputs.rs")
            .replace("// GENERATED_MEMBERS", &members);
        let stamp = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("target")
            .join(format!("bindgen-compile-{}-{stamp}", std::process::id()));
        fs::create_dir_all(&directory).unwrap();
        struct Cleanup(PathBuf);
        impl Drop for Cleanup {
            fn drop(&mut self) {
                let _ = fs::remove_dir_all(&self.0);
            }
        }
        let _cleanup = Cleanup(directory.clone());
        let source_path = directory.join("safe_inputs.rs");
        let executable = directory.join(format!("safe_inputs{}", std::env::consts::EXE_SUFFIX));
        fs::write(&source_path, source).unwrap();
        let compiled = Command::new("rustc")
            .args(["--edition=2021", "--crate-name", "safe_inputs"])
            .arg(&source_path)
            .arg("-o")
            .arg(&executable)
            .output()
            .unwrap();
        assert!(
            compiled.status.success(),
            "{}",
            String::from_utf8_lossy(&compiled.stderr)
        );
        let executed = Command::new(executable).output().unwrap();
        assert!(
            executed.status.success(),
            "{}",
            String::from_utf8_lossy(&executed.stderr)
        );
    }
}

fn to_snake(name: &str) -> String {
    let mut out = String::new();
    for (index, character) in name.chars().enumerate() {
        if character.is_uppercase() {
            if index > 0 {
                out.push('_');
            }
            out.extend(character.to_lowercase());
        } else {
            out.push(character);
        }
    }
    out
}
